class AcquisitionSource:
    """Base class for all planetary knowledge acquisition sources."""
    source_name: str = ''
    entity_type: EntityType = EntityType.REPOSITORY
    base_url: str = ''
    interval_seconds: float = 86400.0
    confidence: float = 0.8

    def fetch(self) -> list[AcquisitionRecord]:
        raise NotImplementedError

    def fetch_one(self, external_id: str) -> AcquisitionRecord | None:
        raise NotImplementedError

    def to_entity(self, record: AcquisitionRecord) -> dict[str, Any]:
        return {'uid': record.external_id, 'name': record.name, 'entity_type': record.entity_type.value, 'description': record.description, 'metadata': {'source': record.source, 'confidence': record.confidence, 'tags': record.tags, 'properties': dict(record.metadata)}, 'attributes': dict(record.raw_data)}

    def summary(self) -> dict[str, Any]:
        return {'source_name': self.source_name, 'entity_type': self.entity_type.value, 'base_url': self.base_url, 'interval_seconds': self.interval_seconds}

class AcquisitionPipeline:
    """Orchestrates multiple acquisition sources and stores into UnifiedGraph."""

    def __init__(self, graph=None):
        self.sources: dict[str, AcquisitionSource] = {}
        self.graph = graph
        self.history: dict[str, list[dict[str, Any]]] = {}

    def register(self, source: AcquisitionSource):
        self.sources[source.source_name] = source

    def register_many(self, *sources: AcquisitionSource):
        for s in sources:
            self.register(s)

    def acquire_all(self) -> dict[str, int]:
        results: dict[str, int] = {}
        for name, source in self.sources.items():
            count = self._acquire_source(source)
            results[name] = count
        return results

    def acquire_source(self, name: str) -> int:
        source = self.sources.get(name)
        if not source:
            raise ValueError(f'Unknown source: {name}')
        return self._acquire_source(source)

    def _acquire_source(self, source: AcquisitionSource) -> int:
        try:
            records = source.fetch()
        except Exception as e:
            self._record_history(source.source_name, 'error', str(e))
            return 0
        count = 0
        for record in records:
            if self.graph is not None:
                entity_dict = source.to_entity(record)
                entity = _UnifiedEntity(uid=entity_dict['uid'], name=entity_dict['name'], entity_type=EntityType(entity_dict['entity_type']), description=entity_dict['description'])
                if entity_dict.get('metadata'):
                    md = entity_dict['metadata']
                    entity.metadata.source = md.get('source', '')
                    entity.metadata.confidence = md.get('confidence', 1.0)
                    entity.metadata.tags = md.get('tags', [])
                    entity.metadata.properties.update(md.get('properties', {}))
                entity.attributes.update(entity_dict.get('attributes', {}))
                self.graph.add_entity(entity)
            count += 1
        self._record_history(source.source_name, 'success', count)
        return count

    def _record_history(self, source: str, status: str, detail: Any):
        if source not in self.history:
            self.history[source] = []
        self.history[source].append({'timestamp': time.time(), 'status': status, 'detail': detail})

    def list_sources(self) -> list[dict[str, Any]]:
        return [s.summary() for s in self.sources.values()]

    def summary(self) -> dict[str, Any]:
        return {'source_count': len(self.sources), 'source_names': sorted(self.sources.keys()), 'history': {k: v[-5:] for k, v in self.history.items()}}

class AcquisitionOrchestrator:
    """
    Orchestrates the full acquisition lifecycle.

    Integrates with OS components via callbacks:
      - Scheduler: periodic acquisition runs
      - Queue: work items for targeted fetches
      - ObservationManager: metrics on acquisition throughput
      - RecoveryManager: event handlers for failures
      - CheckpointManager: state persistence hooks
    """

    def __init__(self, graph=None, persistence_dir: str=''):
        self.pipeline = AcquisitionPipeline(graph=graph)
        self.persistence_dir = Path(persistence_dir or '~/.venus/acquisition').expanduser()
        self.persistence_dir.mkdir(parents=True, exist_ok=True)
        self._last_run: dict[str, float] = {}
        self._stats: dict[str, dict[str, Any]] = {}

    def register_all_sources(self, config: dict[str, Any] | None=None):
        cfg = config or {}
        sources: list[AcquisitionSource] = [GitHubSource(token=cfg.get('github_token', ''), orgs=cfg.get('github_orgs', [])), GitLabSource(token=cfg.get('gitlab_token', ''), groups=cfg.get('gitlab_groups', [])), NPMSource(packages=cfg.get('npm_packages', [])), PyPISource(packages=cfg.get('pypi_packages', [])), CargoSource(crates=cfg.get('cargo_crates', [])), MavenSource(artifacts=cfg.get('maven_artifacts', [])), NuGetSource(packages=cfg.get('nuget_packages', [])), GoSource(modules=cfg.get('go_modules', [])), DockerSource(images=cfg.get('docker_images', [])), RFCSource(rfc_numbers=cfg.get('rfc_numbers', [])), CVESource(cve_ids=cfg.get('cve_ids', [])), NISTSource(publications=cfg.get('nist_publications', [])), CNCFSource(projects=cfg.get('cncf_projects', [])), OWASPSource(projects=cfg.get('owasp_projects', [])), IETFSource(documents=cfg.get('ietf_documents', [])), W3CSource(specs=cfg.get('w3c_specs', [])), ADRSource(adr_urls=cfg.get('adr_urls', []))]
        self.pipeline.register_many(*sources)

    def run_once(self, source_name: str='') -> dict[str, int]:
        if source_name:
            count = self.pipeline.acquire_source(source_name)
            result = {source_name: count}
        else:
            result = self.pipeline.acquire_all()
        now = time.time()
        for name in result:
            self._last_run[name] = now
        self._update_stats(result)
        self._save_state()
        return result

    def _update_stats(self, results: dict[str, int]):
        for name, count in results.items():
            if name not in self._stats:
                self._stats[name] = {'total_items': 0, 'total_runs': 0, 'last_count': 0, 'error_count': 0}
            self._stats[name]['total_items'] += count
            self._stats[name]['total_runs'] += 1
            self._stats[name]['last_count'] = count
            if count == 0:
                self._stats[name]['error_count'] += 1

    def run_all(self) -> dict[str, int]:
        return self.run_once()

    def get_last_run(self, source: str) -> float:
        return self._last_run.get(source, 0.0)

    def get_stats(self) -> dict[str, Any]:
        return dict(self._stats)

    def summary(self) -> dict[str, Any]:
        return {'pipeline': self.pipeline.summary(), 'stats': self._stats, 'last_run_count': len(self._last_run), 'sources_last_run': {k: time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(v)) for k, v in self._last_run.items()}}

    def _save_state(self):
        state = {'last_run': self._last_run, 'stats': self._stats, 'updated_at': time.time()}
        path = self.persistence_dir / 'orchestrator_state.json'
        try:
            path.write_text(json.dumps(state, indent=2, default=str))
        except Exception:
            pass

    def load_state(self):
        path = self.persistence_dir / 'orchestrator_state.json'
        if path.exists():
            try:
                state = json.loads(path.read_text())
                self._last_run = state.get('last_run', {})
                self._stats = state.get('stats', {})
            except Exception:
                pass

class Request:
    """An API request."""

    def __init__(self, method: str='GET', path: str='/', params: dict | None=None, body: Any=None):
        self.method = method
        self.path = path
        self.params = params or {}
        self.body = body

class Response:
    """An API response."""

    def __init__(self, status: int=200, data: Any=None, error: str=''):
        self.status = status
        self.data = data
        self.error = error

    def to_dict(self) -> dict[str, Any]:
        return {'status': self.status, 'data': self.data, 'error': self.error, 'timestamp': datetime.now(timezone.utc).isoformat()}

    def to_json(self) -> str:
        return json.dumps(self.to_dict(), indent=2, default=str)

class APIRouter:
    """API router. Routes requests to the appropriate capability handlers."""

    def __init__(self):
        self._routes: dict[str, dict[str, Any]] = {}
        self._register_core_routes()

    def _register_core_routes(self):
        routes = [('GET', '/v1/search', 'Search across all documents and entities'), ('POST', '/v1/search/advanced', 'Advanced search with filters'), ('POST', '/v1/compile', 'Compile a source file into UIR'), ('GET', '/v1/compile/{path}', 'Get compilation result'), ('POST', '/v1/validate', 'Validate an artifact'), ('GET', '/v1/validate/{path}', 'Get validation results'), ('POST', '/v1/generate', 'Generate artifacts from compilation'), ('GET', '/v1/generate/{compilation_id}', 'Get generated artifacts'), ('GET', '/v1/navigate/{path}', 'Navigate to a specific entity'), ('GET', '/v1/navigate/{path}/children', 'List children of an entity'), ('GET', '/v1/graph', 'Get knowledge graph summary'), ('GET', '/v1/graph/nodes', 'List all graph nodes'), ('GET', '/v1/graph/edges', 'List all graph edges'), ('GET', '/v1/graph/node/{node_id}', 'Get specific node'), ('GET', '/v1/graph/node/{node_id}/neighbors', 'Get node neighbors'), ('GET', '/v1/ontology/types', 'List all ontology types'), ('GET', '/v1/ontology/types/{name}', 'Get type details'), ('GET', '/v1/ontology/entities', 'List entities by type'), ('GET', '/v1/memory', 'Get memory summary'), ('POST', '/v1/memory/query', 'Query institutional memory'), ('GET', '/v1/schemas', 'List all schemas'), ('GET', '/v1/schemas/{name}', 'Get specific schema'), ('GET', '/v1/capabilities', 'List all capabilities'), ('GET', '/v1/capabilities/{name}', 'Get capability details'), ('GET', '/v1/projects', 'List projects'), ('POST', '/v1/projects', 'Create project'), ('GET', '/v1/artifacts', 'List generated artifacts'), ('GET', '/v1/artifacts/{path}', 'Get artifact content'), ('GET', '/v1/runtime', 'Get runtime status'), ('POST', '/v1/runtime/execute', 'Execute a workflow'), ('GET', '/v1/runtime/workflows', 'List workflows'), ('POST', '/v1/runtime/workflows', 'Create a workflow'), ('GET', '/v1/health', 'Platform health check'), ('GET', '/v1/health/detailed', 'Detailed health information')]
        for method, path, description in routes:
            key = f'{method}:{path}'
            self._routes[key] = {'method': method, 'path': path, 'description': description, 'handler': None, 'registered': False}

    def register_handler(self, method: str, path: str, handler: callable):
        key = f'{method}:{path}'
        if key in self._routes:
            self._routes[key]['handler'] = handler
            self._routes[key]['registered'] = True

    def handle(self, request: Request) -> Response:
        key = f'{request.method}:{request.path}'
        route = self._routes.get(key)
        if not route:
            return self._match_parametrized(request)
        if route['handler']:
            try:
                result = route['handler'](request)
                return Response(200, result)
            except Exception as e:
                return Response(500, error=str(e))
        return Response(501, error=f'Handler not registered: {key}')

    def _match_parametrized(self, request: Request) -> Response:
        """Match parameterized routes like /v1/compile/{path}."""
        for key, route in self._routes.items():
            method_match = route['method'] == request.method
            if not method_match:
                continue
            route_parts = route['path'].split('/')
            request_parts = request.path.split('/')
            if len(route_parts) != len(request_parts):
                continue
            params = {}
            match = True
            for rp, rqp in zip(route_parts, request_parts):
                if rp.startswith('{') and rp.endswith('}'):
                    params[rp[1:-1]] = rqp
                elif rp != rqp:
                    match = False
                    break
            if match and route.get('handler'):
                request.params.update(params)
                try:
                    result = route['handler'](request)
                    return Response(200, result)
                except Exception as e:
                    return Response(500, error=str(e))
        return Response(404, error=f'Route not found: {request.method} {request.path}')

    def list_routes(self) -> list[dict[str, Any]]:
        return [{'method': r['method'], 'path': r['path'], 'description': r['description'], 'registered': r['registered']} for r in self._routes.values()]

    def health_check(self) -> dict[str, Any]:
        total = len(self._routes)
        registered = sum((1 for r in self._routes.values() if r['registered']))
        return {'status': 'healthy' if registered > 0 else 'degraded', 'total_routes': total, 'registered_routes': registered, 'coverage': f'{round(registered / total * 100, 1)}%' if total > 0 else '0%'}

def _match_parametrized(self, request: Request) -> Response:
    """Match parameterized routes like /v1/compile/{path}."""
    for key, route in self._routes.items():
        method_match = route['method'] == request.method
        if not method_match:
