class CognitiveArchitecture:
    """Unified cognitive architecture for the Engineering Brain.

    Integrates all cognitive subsystems:
    - Belief system for knowledge representation with uncertainty
    - Goal hierarchy for intentional behavior
    - Reasoning engine for causal/counterfactual/Bayesian inference
    - Working memory for active information
    - Episodic memory for experience tracking
    - Attention mechanism for focus management
    - Reflection engine for self-improvement
    - Strategy engine for tool selection and planning
    - Decision engine for multi-criteria decisions
    - Orchestrator for multi-agent coordination
    """

    def __init__(self):
        self._beliefs = BeliefSystem()
        self._goals = GoalHierarchy()
        self._reasoning = ReasoningEngine()
        self._memory_working = WorkingMemory()
        self._memory_episodic = EpisodicMemory()
        self._attention = AttentionMechanism()
        self._reflection = ReflectionEngine()
        self._strategy = StrategyEngine()
        self._decision = DecisionEngine()
        self._orchestrator = Orchestrator()
        self._started_at = __import__('time').time()

    @property
    def beliefs(self) -> BeliefSystem:
        return self._beliefs

    @property
    def goals(self) -> GoalHierarchy:
        return self._goals

    @property
    def reasoning(self) -> ReasoningEngine:
        return self._reasoning

    @property
    def memory_working(self) -> WorkingMemory:
        return self._memory_working

    @property
    def memory_episodic(self) -> EpisodicMemory:
        return self._memory_episodic

    @property
    def attention(self) -> AttentionMechanism:
        return self._attention

    @property
    def reflection(self) -> ReflectionEngine:
        return self._reflection

    @property
    def strategy(self) -> StrategyEngine:
        return self._strategy

    @property
    def decision(self) -> DecisionEngine:
        return self._decision

    @property
    def orchestrator(self) -> Orchestrator:
        return self._orchestrator

    def observe(self, description: str, entities: list[str] | None=None, importance: float=0.5, tags: list[str] | None=None):
        """Record an observation in episodic memory and working memory."""
        self._memory_episodic.record(event_type='observation', description=description, entities=entities, importance=importance, tags=tags)
        self._memory_working.store(content=description, content_type='observation', salience=importance)

    def think(self, description: str, beliefs_before: dict[str, float] | None=None, beliefs_after: dict[str, float] | None=None):
        """Record a cognitive event (inference, decision) in episodic memory."""
        self._memory_episodic.record(event_type='inference', description=description, beliefs_before=beliefs_before or {}, beliefs_after=beliefs_after or {}, importance=0.7)

    def reflect(self) -> list[Reflection]:
        """Run reflection over recent episodic memory."""
        recent = self._memory_episodic.recent(50)
        return self._reflection.analyze_decisions(recent)

    def decide(self, alternatives: list[Alternative], criteria: list[str] | None=None) -> Decision:
        """Run decision and record the outcome."""
        decision = self._decision.evaluate(alternatives, criteria)
        self._memory_episodic.record(event_type='decision', description=f'Decision: {decision.context} → {decision.selected_id}', entities=[decision.selected_id], outcome='pending', importance=0.8)
        return decision

    def tick(self):
        """Run one cognitive cycle: decay attention and working memory salience."""
        self._attention.decay()
        self._memory_working.decay_all(rate=0.05)

    def summary(self) -> dict[str, Any]:
        return {'beliefs': self._beliefs.summary(), 'goals': self._goals.summary(), 'reasoning': self._reasoning.summary(), 'working_memory': self._memory_working.summary(), 'episodic_memory': self._memory_episodic.summary(), 'attention': self._attention.summary(), 'reflection': self._reflection.summary(), 'strategy': self._strategy.summary(), 'decision': self._decision.summary(), 'orchestrator': self._orchestrator.summary()}

def think(self, description: str, beliefs_before: dict[str, float] | None=None, beliefs_after: dict[str, float] | None=None):
    """Record a cognitive event (inference, decision) in episodic memory."""
    self._memory_episodic.record(event_type='inference', description=description, beliefs_before=beliefs_before or {}, beliefs_after=beliefs_after or {}, importance=0.7)

def reflect(self) -> list[Reflection]:
    """Run reflection over recent episodic memory."""
    recent = self._memory_episodic.recent(50)
    return self._reflection.analyze_decisions(recent)

@dataclass
class AttentionFocus:
    """What the cognitive system is currently focused on."""
    id: str = ''
    target_type: str = ''
    target_id: str = ''
    description: str = ''
    salience: float = 0.0
    source: str = ''
    created_at: float = 0.0
    duration: float = 0.0

    def __post_init__(self):
        if not self.id:
            self.id = generate_id('focus', 10)
        if not self.created_at:
            self.created_at = time.time()

    @property
    def is_expired(self) -> bool:
        return self.duration > 0 and time.time() - self.created_at > self.duration

class AttentionMechanism:
    """Attention mechanism that determines processing focus.

    Supports:
    - Bottom-up attention: salience-driven (novelty, surprise, importance)
    - Top-down attention: goal-driven (relevant to current goal)
    - Mixed attention: combination of both
    - Focus switching when salience thresholds are exceeded
    """

    def __init__(self, focus_capacity: int=3, surprise_threshold: float=0.3, salience_decay: float=0.05):
        self._foci: list[AttentionFocus] = []
        self._focus_capacity = focus_capacity
        self._surprise_threshold = surprise_threshold
        self._salience_decay = salience_decay
        self._history: list[AttentionFocus] = []

    @property
    def current_focus(self) -> list[AttentionFocus]:
        """Current active foci (not expired)."""
        self._foci = [f for f in self._foci if not f.is_expired]
        return list(self._foci)

    @property
    def primary_focus(self) -> AttentionFocus | None:
        """Highest-salience current focus."""
        foci = self.current_focus
        return max(foci, key=lambda f: f.salience) if foci else None

    def bottom_up(self, target_type: str, target_id: str, description: str='', salience: float=0.5, duration: float=0.0) -> AttentionFocus:
        """Bottom-up attention driven by salience."""
        focus = AttentionFocus(target_type=target_type, target_id=target_id, description=description, salience=salience, source='bottom_up', duration=duration)
        return self._add_focus(focus)

    def top_down(self, target_type: str, target_id: str, description: str='', priority: float=0.5, duration: float=0.0) -> AttentionFocus:
        """Top-down attention driven by goals."""
        focus = AttentionFocus(target_type=target_type, target_id=target_id, description=description, salience=priority, source='top_down', duration=duration)
        return self._add_focus(focus)

    def _add_focus(self, focus: AttentionFocus) -> AttentionFocus:
        existing = next((f for f in self._foci if f.target_id == focus.target_id), None)
        if existing:
            existing.salience = max(existing.salience, focus.salience)
            existing.duration = max(existing.duration, focus.duration)
            self._history.append(focus)
            return existing
        self._foci.append(focus)
        self._history.append(focus)
        while len(self._foci) > self._focus_capacity:
            lowest = min(self._foci, key=lambda f: f.salience)
            self._foci.remove(lowest)
        return focus

    def surprise(self, expected: float, observed: float) -> float:
        """Compute surprise (salience trigger) from prediction error."""
        error = abs(observed - expected)
        return min(1.0, error / max(self._surprise_threshold, 0.01))

    def orient(self, target_type: str, target_id: str, description: str, expected_salience: float, actual_salience: float) -> AttentionFocus | None:
        """Orient attention based on surprise (mismatch between expected and actual)."""
        s = self.surprise(expected_salience, actual_salience)
        if s >= self._surprise_threshold:
            return self.bottom_up(target_type=target_type, target_id=target_id, description=description, salience=s)
        return None

    def decay(self):
        """Decay salience of all foci over time."""
        for focus in self._foci:
            focus.salience = max(0.0, focus.salience - self._salience_decay)
        self._foci = [f for f in self._foci if f.salience > 0]

    def summary(self) -> dict[str, Any]:
        foci = self.current_focus
        return {'active_foci': len(foci), 'capacity': self._focus_capacity, 'primary': self.primary_focus.description if self.primary_focus else None, 'sources': {f.source for f in foci}, 'total_switches': len(self._history)}

@property
def current_focus(self) -> list[AttentionFocus]:
    """Current active foci (not expired)."""
    self._foci = [f for f in self._foci if not f.is_expired]
    return list(self._foci)

@property
def primary_focus(self) -> AttentionFocus | None:
    """Highest-salience current focus."""
    foci = self.current_focus
    return max(foci, key=lambda f: f.salience) if foci else None

def bottom_up(self, target_type: str, target_id: str, description: str='', salience: float=0.5, duration: float=0.0) -> AttentionFocus:
    """Bottom-up attention driven by salience."""
    focus = AttentionFocus(target_type=target_type, target_id=target_id, description=description, salience=salience, source='bottom_up', duration=duration)
    return self._add_focus(focus)

def top_down(self, target_type: str, target_id: str, description: str='', priority: float=0.5, duration: float=0.0) -> AttentionFocus:
    """Top-down attention driven by goals."""
    focus = AttentionFocus(target_type=target_type, target_id=target_id, description=description, salience=priority, source='top_down', duration=duration)
    return self._add_focus(focus)

