            self.id = generate_id('alt', 10)

class DecisionEngine:
    """Multi-criteria decision making with constraint solving.

    Supports multiple decision modes, constraint handling,
    and sensitivity analysis.
    """

    def __init__(self):
        self._decisions: list[Decision] = []
        self._criteria_registry: dict[str, Criterion] = {}
        self._hard_constraints: list[Callable[[Alternative], bool]] = []
        self._soft_constraints: list[tuple[Callable[[Alternative], float], float]] = []

    def register_criterion(self, name: str, weight: float=1.0, higher_is_better: bool=True, ideal: float=1.0) -> Criterion:
        criterion = Criterion(name=name, weight=weight, higher_is_better=higher_is_better, ideal=ideal)
        self._criteria_registry[name] = criterion
        return criterion

    def add_hard_constraint(self, constraint: Callable[[Alternative], bool]):
        """Add a hard constraint that alternatives must satisfy."""
        self._hard_constraints.append(constraint)

    def add_soft_constraint(self, constraint: Callable[[Alternative], float], penalty_weight: float=1.0):
        """Add a soft constraint with penalty for violation."""
        self._soft_constraints.append((constraint, penalty_weight))

    def evaluate(self, alternatives: list[Alternative], criteria: list[str] | None=None, mode: DecisionMode=DecisionMode.WEIGHTED_SUM) -> Decision:
        """Evaluate alternatives and select the best one."""
        if criteria is None:
            criteria = list(self._criteria_registry.keys())
        valid = [a for a in alternatives if all((c(a) for c in self._hard_constraints))]
        if not valid:
            valid = alternatives
        scored: list[tuple[float, Alternative]] = []
        for alt in valid:
            score = self._compute_score(alt, criteria, mode)
            for constraint_fn, penalty in self._soft_constraints:
                violation = constraint_fn(alt)
                score -= violation * penalty
            scored.append((score, alt))
        scored.sort(key=lambda x: x[0], reverse=True)
        if not scored:
            return Decision(context='evaluation', mode=mode, confidence=0.0, rationale='No valid alternatives found', outcome='failure')
        selected = scored[0][1]
        best_score = scored[0][0]
        second_score = scored[1][0] if len(scored) > 1 else 0
        confidence = 1.0 / (1.0 + math.exp(-(best_score - second_score))) if len(scored) > 1 else 0.5
        decision = Decision(context='evaluation', alternatives=[a.id for a in alternatives], selected_id=selected.id, mode=mode, confidence=confidence, rationale=f"Selected '{selected.name}' with score {best_score:.3f}")
        self._decisions.append(decision)
        return decision

    def _compute_score(self, alt: Alternative, criteria: list[str], mode: DecisionMode) -> float:
        if mode == DecisionMode.SATISFICING:
            return 1.0
        if mode == DecisionMode.WEIGHTED_SUM or mode == DecisionMode.EXPECTED_VALUE:
            total = 0.0
            total_weight = 0.0
            for criterion_name in criteria:
                criterion = self._criteria_registry.get(criterion_name)
                if not criterion or criterion_name not in alt.criteria_scores:
                    continue
                raw = alt.criteria_scores[criterion_name]
                normalized = raw / max(criterion.ideal, 0.01)
                if not criterion.higher_is_better:
                    normalized = 1.0 - normalized
                total += normalized * criterion.weight
                total_weight += criterion.weight
            return total / max(total_weight, 0.01)
        return 0.5

    def sensitivity_analysis(self, decision: Decision, alternatives: list[Alternative], criteria: list[str]) -> dict[str, dict[str, float]]:
        """Analyze how sensitive the decision is to criterion weight changes."""
        results: dict[str, dict[str, float]] = {}
        for criterion_name in criteria:
            criterion = self._criteria_registry.get(criterion_name)
            if not criterion:
                continue
            for factor, label in [(0.5, 'halved'), (2.0, 'doubled')]:
                original = criterion.weight
                criterion.weight = original * factor
                decision2 = self.evaluate(alternatives, criteria)
                results[f'{criterion_name}_{label}'] = {'selected': decision2.selected_id, 'changed': decision2.selected_id != decision.selected_id}
                criterion.weight = original
        return results

    def priority_order(self, alternatives: list[Alternative], criteria: list[str] | None=None) -> list[Alternative]:
        """Return alternatives sorted by priority (highest first)."""
        if criteria is None:
            criteria = list(self._criteria_registry.keys())
        scored = [(self._compute_score(a, criteria, DecisionMode.WEIGHTED_SUM), a) for a in alternatives]
        scored.sort(key=lambda x: x[0], reverse=True)
        return [a for _, a in scored]

    def summary(self) -> dict[str, Any]:
        return {'total_decisions': len(self._decisions), 'criteria': list(self._criteria_registry.keys()), 'hard_constraints': len(self._hard_constraints), 'soft_constraints': len(self._soft_constraints), 'recent_decisions': [{'context': d.context, 'selected': d.selected_id, 'outcome': d.outcome} for d in self._decisions[-5:]]}

def add_hard_constraint(self, constraint: Callable[[Alternative], bool]):
    """Add a hard constraint that alternatives must satisfy."""
    self._hard_constraints.append(constraint)

def add_soft_constraint(self, constraint: Callable[[Alternative], float], penalty_weight: float=1.0):
    """Add a soft constraint with penalty for violation."""
    self._soft_constraints.append((constraint, penalty_weight))

def sensitivity_analysis(self, decision: Decision, alternatives: list[Alternative], criteria: list[str]) -> dict[str, dict[str, float]]:
    """Analyze how sensitive the decision is to criterion weight changes."""
    results: dict[str, dict[str, float]] = {}
    for criterion_name in criteria:
        criterion = self._criteria_registry.get(criterion_name)
        if not criterion:
            continue
        for factor, label in [(0.5, 'halved'), (2.0, 'doubled')]:
            original = criterion.weight
            criterion.weight = original * factor
            decision2 = self.evaluate(alternatives, criteria)
            results[f'{criterion_name}_{label}'] = {'selected': decision2.selected_id, 'changed': decision2.selected_id != decision.selected_id}
            criterion.weight = original
    return results

class GoalHierarchy:
    """Manages a tree of goals with decomposition, priority, and dependency resolution.

    Supports:
    - Goal creation and hierarchical decomposition
    - Dependency tracking and blocking detection
    - Priority-based ordering
    - Progress computation (rolls up from children)
    - Integration with Planning subsystem for plan creation
    """

    def __init__(self):
        self._goals: dict[str, Goal] = {}
        self._index_by_owner: dict[str, list[str]] = {}
        self._index_by_status: dict[str, list[str]] = {}

    @property
    def goal_count(self) -> int:
        return len(self._goals)

    def create_goal(self, name: str, description: str='', priority: GoalPriority=GoalPriority.MEDIUM, parent_id: str='', dependency_ids: list[str] | None=None, estimated_effort: float=0.0, owner: str='', justification: str='', success_criteria: list[str] | None=None, tags: list[str] | None=None) -> Goal:
        goal = Goal(name=name, description=description, priority=priority, parent_id=parent_id, dependency_ids=dependency_ids or [], estimated_effort=estimated_effort, owner=owner, justification=justification, success_criteria=success_criteria or [], tags=tags or [])
        if parent_id and parent_id in self._goals:
            parent = self._goals[parent_id]
            if goal.id not in parent.child_ids:
                parent.child_ids.append(goal.id)
            parent.updated_at = time.time()
        for dep_id in goal.dependency_ids:
            dep = self._goals.get(dep_id)
            if dep and goal.id not in dep.depends_on_me:
                dep.depends_on_me.append(goal.id)
        self._goals[goal.id] = goal
        self._reindex(goal)
        self._update_blocked_status(goal)
        return goal

    def get(self, goal_id: str) -> Goal | None:
        return self._goals.get(goal_id)

    def find(self, status: GoalStatus | None=None, priority: GoalPriority | None=None, owner: str='', tag: str='') -> list[Goal]:
        results: list[Goal] = []
        if owner:
            ids = self._index_by_owner.get(owner, [])
            results = [self._goals[gid] for gid in ids if gid in self._goals]
        else:
            results = list(self._goals.values())
        if status:
            results = [g for g in results if g.status == status]
        if priority:
            results = [g for g in results if g.priority == priority]
        if tag:
            results = [g for g in results if tag in g.tags]
        return results

    def update_progress(self, goal_id: str, progress: float):
        goal = self._goals.get(goal_id)
        if not goal:
            return
        goal.progress = min(1.0, max(0.0, progress))
        goal.updated_at = time.time()
        if progress >= 1.0:
            goal.status = GoalStatus.ACHIEVED
        elif progress > 0:
            goal.status = GoalStatus.IN_PROGRESS
        self._reindex(goal)
        self._rollup_progress(goal_id)

    def _rollup_progress(self, goal_id: str):
        goal = self._goals.get(goal_id)
        if not goal or not goal.parent_id:
            return
        parent = self._goals.get(goal.parent_id)
        if not parent:
            return
        children = [self._goals[cid] for cid in parent.child_ids if cid in self._goals]
        if children:
            parent.progress = sum((c.progress for c in children)) / len(children)
            parent.updated_at = time.time()
        self._rollup_progress(goal.parent_id)

    def decompose(self, parent_id: str, subgoals: list[dict[str, Any]]) -> list[Goal]:
        """Decompose a goal into subgoals."""
        parent = self._goals.get(parent_id)
        if not parent:
            return []
        children = []
        for sg in subgoals:
            child = self.create_goal(name=sg.get('name', ''), description=sg.get('description', ''), priority=sg.get('priority', parent.priority), parent_id=parent_id, dependency_ids=sg.get('dependency_ids'), estimated_effort=sg.get('estimated_effort', 0.0), owner=sg.get('owner', parent.owner), justification=sg.get('justification', parent.justification), success_criteria=sg.get('success_criteria'), tags=sg.get('tags', parent.tags.copy()))
            children.append(child)
        parent.status = GoalStatus.ACTIVE
        parent.updated_at = time.time()
        return children

    def _update_blocked_status(self, goal: Goal):
        """Check if a goal is blocked by unmet dependencies."""
        for dep_id in goal.dependency_ids:
            dep = self._goals.get(dep_id)
            if dep and dep.status != GoalStatus.ACHIEVED:
                goal.status = GoalStatus.BLOCKED
                goal.updated_at = time.time()
                return

    def priorities(self, status: GoalStatus | None=GoalStatus.ACTIVE) -> list[Goal]:
        """Get goals sorted by priority (most urgent first), optionally filtered by status."""
        candidates = self.find(status=status) if status else list(self._goals.values())
        return sorted(candidates, key=lambda g: (g.priority.value, g.deadline or float('inf')))

    def get_chain(self, goal_id: str) -> list[Goal]:
        """Get the full chain from root to this goal."""
        chain: list[Goal] = []
        current = self._goals.get(goal_id)
        while current:
            chain.append(current)
            current = self._goals.get(current.parent_id) if current.parent_id else None
        return list(reversed(chain))

    def _reindex(self, goal: Goal):
        self._index_by_owner.setdefault(goal.owner, [])
        if goal.id not in self._index_by_owner[goal.owner]:
            self._index_by_owner[goal.owner].append(goal.id)
        self._index_by_status.setdefault(goal.status.value, [])
        if goal.id not in self._index_by_status[goal.status.value]:
            self._index_by_status[goal.status.value].append(goal.id)

    def summary(self) -> dict[str, Any]:
        status_counts: dict[str, int] = {}
        priority_counts: dict[str, int] = {}
        for g in self._goals.values():
            status_counts[g.status.value] = status_counts.get(g.status.value, 0) + 1
            priority_counts[g.priority.name] = priority_counts.get(g.priority.name, 0) + 1
        return {'total_goals': len(self._goals), 'by_status': status_counts, 'by_priority': priority_counts, 'average_progress': sum((g.progress for g in self._goals.values())) / max(len(self._goals), 1), 'blocked_goals': len([g for g in self._goals.values() if g.status == GoalStatus.BLOCKED])}

def _update_blocked_status(self, goal: Goal):
    """Check if a goal is blocked by unmet dependencies."""
    for dep_id in goal.dependency_ids:
        dep = self._goals.get(dep_id)
        if dep and dep.status != GoalStatus.ACHIEVED:
            goal.status = GoalStatus.BLOCKED
            goal.updated_at = time.time()
            return

def priorities(self, status: GoalStatus | None=GoalStatus.ACTIVE) -> list[Goal]:
    """Get goals sorted by priority (most urgent first), optionally filtered by status."""
    candidates = self.find(status=status) if status else list(self._goals.values())
    return sorted(candidates, key=lambda g: (g.priority.value, g.deadline or float('inf')))

def get_chain(self, goal_id: str) -> list[Goal]:
    """Get the full chain from root to this goal."""
    chain: list[Goal] = []
    current = self._goals.get(goal_id)
    while current:
        chain.append(current)
        current = self._goals.get(current.parent_id) if current.parent_id else None
    return list(reversed(chain))

@dataclass
class WorkingMemorySlot:
    """A single item in working memory."""
    id: str = ''
    content: str = ''
    content_type: str = 'text'
    source: str = ''
    salience: float = 0.5
    created_at: float = 0.0
    last_accessed: float = 0.0
    access_count: int = 0
    metadata: dict[str, Any] = field(default_factory=dict)

    def __post_init__(self):
        if not self.id:
            self.id = generate_id('wm', 10)
        now = time.time()
        if not self.created_at:
            self.created_at = now
        if not self.last_accessed:
            self.last_accessed = now

class WorkingMemory:
    """Limited-capacity working memory with salience-based eviction.

    Capacity defaults to 7 ± 2 items (Miller's Law).
    Items with lowest salience are evicted when capacity is exceeded.
    """

    def __init__(self, capacity: int=7):
        self._slots: dict[str, WorkingMemorySlot] = {}
        self._capacity = capacity
        self._eviction_count = 0

    @property
    def size(self) -> int:
        return len(self._slots)

    @property
    def capacity(self) -> int:
        return self._capacity

    @property
    def utilization(self) -> float:
        return len(self._slots) / self._capacity

    def store(self, content: str, content_type: str='text', source: str='', salience: float=0.5, **metadata) -> WorkingMemorySlot:
        slot = WorkingMemorySlot(content=content, content_type=content_type, source=source, salience=salience, metadata=metadata)
        self._slots[slot.id] = slot
        self._evict_if_needed()
        return slot

    def get(self, slot_id: str) -> WorkingMemorySlot | None:
        slot = self._slots.get(slot_id)
        if slot:
            slot.last_accessed = time.time()
            slot.access_count += 1
        return slot

    def retrieve(self, content_contains: str='', content_type: str='', min_salience: float=0.0) -> list[WorkingMemorySlot]:
        results = list(self._slots.values())
        if content_contains:
            results = [s for s in results if content_contains.lower() in s.content.lower()]
        if content_type:
            results = [s for s in results if s.content_type == content_type]
        if min_salience > 0:
            results = [s for s in results if s.salience >= min_salience]
        return sorted(results, key=lambda s: s.salience, reverse=True)

    def focus(self) -> WorkingMemorySlot | None:
        """Return the highest-salience item (attention focus)."""
        if not self._slots:
            return None
        return max(self._slots.values(), key=lambda s: s.salience)

    def update_salience(self, slot_id: str, delta: float):
        """Increase or decrease salience of a working memory item."""
        slot = self._slots.get(slot_id)
        if slot:
            slot.salience = max(0.0, min(1.0, slot.salience + delta))

    def decay_all(self, rate: float=0.1):
        """Decay salience of all items."""
        for slot in list(self._slots.values()):
            slot.salience = max(0.0, slot.salience - rate)
            if slot.salience <= 0:
                del self._slots[slot.id]
                self._eviction_count += 1

    def clear(self):
        self._slots.clear()

    def _evict_if_needed(self):
        while len(self._slots) > self._capacity:
            lowest = min(self._slots.values(), key=lambda s: s.salience)
            del self._slots[lowest.id]
            self._eviction_count += 1

    def summary(self) -> dict[str, Any]:
        types: dict[str, int] = {}
        for s in self._slots.values():
            types[s.content_type] = types.get(s.content_type, 0) + 1
        return {'size': self.size, 'capacity': self._capacity, 'utilization': round(self.utilization, 2), 'by_type': types, 'eviction_count': self._eviction_count, 'focus': self.focus().content if self.focus() else None}

class EpisodicMemory:
    """Episodic memory — stores and retrieves timestamped cognitive episodes.

    Supports retrieval by:
    - Recency (most recent events first)
    - Relevance (matching entity IDs or tags)
    - Importance threshold
    - Pattern matching (events of a specific type)
    """

    def __init__(self, max_entries: int=10000):
        self._entries: list[EpisodicMemoryEntry] = []
        self._max_entries = max_entries
        self._index_by_type: dict[str, list[int]] = defaultdict(list)
        self._index_by_entity: dict[str, list[int]] = defaultdict(list)

    @property
    def entry_count(self) -> int:
        return len(self._entries)

    def record(self, event_type: str, description: str, entities: list[str] | None=None, beliefs_before: dict[str, float] | None=None, beliefs_after: dict[str, float] | None=None, outcome: str='unknown', importance: float=0.5, tags: list[str] | None=None, **metadata) -> EpisodicMemoryEntry:
        entry = EpisodicMemoryEntry(event_type=event_type, description=description, entities=entities or [], beliefs_before=beliefs_before or {}, beliefs_after=beliefs_after or {}, outcome=outcome, importance=importance, tags=tags or [], metadata=metadata)
        idx = len(self._entries)
        self._entries.append(entry)
        self._index_by_type[entry.event_type].append(idx)
        for eid in entry.entities:
            self._index_by_entity[eid].append(idx)
        if len(self._entries) > self._max_entries:
            excess = len(self._entries) - self._max_entries
            self._entries = self._entries[excess:]
            self._rebuild_indexes()
        return entry

    def recent(self, limit: int=10) -> list[EpisodicMemoryEntry]:
        """Most recent episodes."""
        return list(reversed(self._entries[-limit:]))

    def by_type(self, event_type: str, limit: int=20) -> list[EpisodicMemoryEntry]:
        indices = self._index_by_type.get(event_type, [])
        entries = [self._entries[i] for i in indices if i < len(self._entries)]
        return list(reversed(entries))[:limit]

    def by_entity(self, entity_id: str, limit: int=20) -> list[EpisodicMemoryEntry]:
        indices = self._index_by_entity.get(entity_id, [])
        entries = [self._entries[i] for i in indices if i < len(self._entries)]
        return list(reversed(entries))[:limit]

    def search(self, query: str='', min_importance: float=0.0, limit: int=20) -> list[EpisodicMemoryEntry]:
        results: list[EpisodicMemoryEntry] = []
        for entry in reversed(self._entries):
            if len(results) >= limit:
                break
            if entry.importance < min_importance:
                continue
            if query and query.lower() not in entry.description.lower():
                continue
            results.append(entry)
        return results

    def replay(self, event_type: str) -> list[dict[str, Any]]:
        """Replay all episodes of a given type — useful for reflection."""
        entries = self.by_type(event_type)
        return [{'timestamp': e.timestamp, 'description': e.description, 'outcome': e.outcome, 'beliefs_before': e.beliefs_before, 'beliefs_after': e.beliefs_after} for e in entries]

    def _rebuild_indexes(self):
        self._index_by_type.clear()
        self._index_by_entity.clear()
        for i, entry in enumerate(self._entries):
            self._index_by_type[entry.event_type].append(i)
            for eid in entry.entities:
                self._index_by_entity[eid].append(i)

    def summary(self) -> dict[str, Any]:
        type_counts: dict[str, int] = {}
        for e in self._entries:
            type_counts[e.event_type] = type_counts.get(e.event_type, 0) + 1
        return {'total_entries': len(self._entries), 'max_entries': self._max_entries, 'by_type': type_counts, 'recent_outcomes': [e.outcome for e in self._entries[-5:]]}

def focus(self) -> WorkingMemorySlot | None:
    """Return the highest-salience item (attention focus)."""
    if not self._slots:
        return None
    return max(self._slots.values(), key=lambda s: s.salience)

def update_salience(self, slot_id: str, delta: float):
    """Increase or decrease salience of a working memory item."""
    slot = self._slots.get(slot_id)
    if slot:
        slot.salience = max(0.0, min(1.0, slot.salience + delta))

def decay_all(self, rate: float=0.1):
    """Decay salience of all items."""
    for slot in list(self._slots.values()):
        slot.salience = max(0.0, slot.salience - rate)
        if slot.salience <= 0:
            del self._slots[slot.id]
            self._eviction_count += 1

def recent(self, limit: int=10) -> list[EpisodicMemoryEntry]:
    """Most recent episodes."""
    return list(reversed(self._entries[-limit:]))

@dataclass
class CognitiveAgent:
    """An agent in the cognitive architecture."""
    id: str = ''
    name: str = ''
    agent_type: str = ''
    capabilities: list[str] = field(default_factory=list)
