            if gene_count > 0:
                type_counts: dict[str, int] = {}
                for g in genome.all_genes:
                    type_counts[g.gene_type.name.lower()] = type_counts.get(g.gene_type.name.lower(), 0) + 1
                findings.append(ResearchFinding(id=generate_id('arch', 12), title=f'Gene composition: {len(type_counts)} types', description=f'Gene type distribution: {type_counts}', evidence=f'Total genes: {gene_count}', confidence=0.9, impact=0.2, tags=['composition', 'gene_types']))
        if twin:
            all_edges = []
            if hasattr(twin, 'find_edges'):
                all_edges = twin.find_edges()
            if all_edges:
                hub_modules = self._find_hubs(all_edges)
                if hub_modules:
                    findings.append(ResearchFinding(id=generate_id('arch', 12), title=f'Hubs detected: {len(hub_modules)} modules', description=f'Highly coupled modules: {hub_modules[:5]}', evidence=f'Total edges: {len(all_edges)}', confidence=0.6, impact=-0.3, tags=['hub', 'coupling', 'bottleneck']))
        return findings

    def generate_questions(self, context: dict[str, Any]) -> list[ResearchQuestion]:
        return [ResearchQuestion(question='What is the optimal coupling range for this architecture?', hypothesis='Coupling between 0.3 and 0.7 correlates with highest fitness', priority=0.8, status='open', created_at=time.time()), ResearchQuestion(question='Which modules are architectural bottlenecks?', hypothesis='Modules with >5 incoming dependencies degrade maintainability', priority=0.7, status='open', created_at=time.time()), ResearchQuestion(question='Is there evidence of architectural drift?', hypothesis='Growing module count without layer boundaries indicates drift', priority=0.6, status='open', created_at=time.time())]

    def _find_hubs(self, edges: list, threshold: int=5) -> list[str]:
        targets: dict[str, int] = {}
        for e in edges:
            tgt = e[1] if len(e) > 1 else ''
            targets[tgt] = targets.get(tgt, 0) + 1
        return [m for m, c in sorted(targets.items(), key=lambda x: -x[1]) if c >= threshold][:10]

class SecurityScientist(ResearchAgent):
    """Researcher focused on software security."""

    def research_domain(self) -> str:
        return 'software_security'

    def investigate(self, context: dict[str, Any]) -> list[ResearchFinding]:
        findings = []
        extraction = context.get('extraction')
        if extraction and hasattr(extraction, 'security_policies'):
            for sp in extraction.security_policies:
                findings.append(ResearchFinding(id=generate_id('sec', 12), title=f"Security mechanism: {sp['category']}", description=f"Detected {sp.get('evidence_count', 0)} instances of {sp['category']}", evidence=f"Confidence: {sp.get('confidence', 0.5):.2f}", confidence=sp.get('confidence', 0.5), impact=0.4, tags=['security', sp['category']]))
        repo_path = context.get('repo_path')
        if repo_path:
            path = Path(repo_path)
            secrets = self._scan_secrets(path)
            if secrets:
                findings.append(ResearchFinding(id=generate_id('sec', 12), title=f'Potential secrets: {len(secrets)}', description=f'Files with potential secrets: {secrets[:5]}', evidence='Detected using pattern matching', confidence=0.5, impact=-0.7, tags=['security', 'secrets', 'risk']))
        return findings

    def generate_questions(self, context: dict[str, Any]) -> list[ResearchQuestion]:
        return [ResearchQuestion(question='What is the security posture of this repository?', hypothesis='Repos with auth, encryption, and validation have fewer vulnerabilities', priority=0.8, status='open', created_at=time.time()), ResearchQuestion(question='Are there hardcoded secrets?', hypothesis='Secret keys in source code are the most common security risk', priority=0.9, status='open', created_at=time.time())]

    def _scan_secrets(self, path: Path) -> list[str]:
        secret_patterns = ['SECRET_KEY\\s*=\\s*["\\\'][^"\\\']+["\\\']', 'API_KEY\\s*=\\s*["\\\'][^"\\\']+["\\\']', 'PASSWORD\\s*=\\s*["\\\'][^"\\\']+["\\\']', 'api_key\\s*=\\s*["\\\'][^"\\\']+["\\\']', 'password\\s*=\\s*["\\\'][^"\\\']+["\\\']']
        hits = []
        for f in path.rglob('*.py'):
            try:
                text = f.read_text(errors='replace')
                for pat in secret_patterns:
                    if re.search(pat, text):
                        hits.append(str(f.relative_to(path)))
                        break
            except Exception:
                continue
        return hits

