class AcquisitionPipeline:
    """Orchestrates multiple acquisition sources and stores into UnifiedGraph."""

    def __init__(self, graph=None):
        self.sources: dict[str, AcquisitionSource] = {}
        self.graph = graph
        self.history: dict[str, list[dict[str, Any]]] = {}

    def register(self, source: AcquisitionSource):
        self.sources[source.source_name] = source

    def register_many(self, *sources: AcquisitionSource):
        for s in sources:
            self.register(s)

    def acquire_all(self) -> dict[str, int]:
        results: dict[str, int] = {}
        for name, source in self.sources.items():
            count = self._acquire_source(source)
            results[name] = count
        return results

    def acquire_source(self, name: str) -> int:
        source = self.sources.get(name)
        if not source:
            raise ValueError(f'Unknown source: {name}')
        return self._acquire_source(source)

    def _acquire_source(self, source: AcquisitionSource) -> int:
        try:
            records = source.fetch()
        except Exception as e:
            self._record_history(source.source_name, 'error', str(e))
            return 0
        count = 0
        for record in records:
            if self.graph is not None:
                entity_dict = source.to_entity(record)
                entity = _UnifiedEntity(uid=entity_dict['uid'], name=entity_dict['name'], entity_type=EntityType(entity_dict['entity_type']), description=entity_dict['description'])
                if entity_dict.get('metadata'):
                    md = entity_dict['metadata']
                    entity.metadata.source = md.get('source', '')
                    entity.metadata.confidence = md.get('confidence', 1.0)
                    entity.metadata.tags = md.get('tags', [])
                    entity.metadata.properties.update(md.get('properties', {}))
                entity.attributes.update(entity_dict.get('attributes', {}))
                self.graph.add_entity(entity)
            count += 1
        self._record_history(source.source_name, 'success', count)
        return count

    def _record_history(self, source: str, status: str, detail: Any):
        if source not in self.history:
            self.history[source] = []
        self.history[source].append({'timestamp': time.time(), 'status': status, 'detail': detail})

    def list_sources(self) -> list[dict[str, Any]]:
        return [s.summary() for s in self.sources.values()]

    def summary(self) -> dict[str, Any]:
        return {'source_count': len(self.sources), 'source_names': sorted(self.sources.keys()), 'history': {k: v[-5:] for k, v in self.history.items()}}

class AcquisitionOrchestrator:
    """
    Orchestrates the full acquisition lifecycle.

    Integrates with OS components via callbacks:
      - Scheduler: periodic acquisition runs
      - Queue: work items for targeted fetches
      - ObservationManager: metrics on acquisition throughput
      - RecoveryManager: event handlers for failures
      - CheckpointManager: state persistence hooks
    """

    def __init__(self, graph=None, persistence_dir: str=''):
        self.pipeline = AcquisitionPipeline(graph=graph)
        self.persistence_dir = Path(persistence_dir or '~/.venus/acquisition').expanduser()
        self.persistence_dir.mkdir(parents=True, exist_ok=True)
        self._last_run: dict[str, float] = {}
        self._stats: dict[str, dict[str, Any]] = {}

    def register_all_sources(self, config: dict[str, Any] | None=None):
        cfg = config or {}
        sources: list[AcquisitionSource] = [GitHubSource(token=cfg.get('github_token', ''), orgs=cfg.get('github_orgs', [])), GitLabSource(token=cfg.get('gitlab_token', ''), groups=cfg.get('gitlab_groups', [])), NPMSource(packages=cfg.get('npm_packages', [])), PyPISource(packages=cfg.get('pypi_packages', [])), CargoSource(crates=cfg.get('cargo_crates', [])), MavenSource(artifacts=cfg.get('maven_artifacts', [])), NuGetSource(packages=cfg.get('nuget_packages', [])), GoSource(modules=cfg.get('go_modules', [])), DockerSource(images=cfg.get('docker_images', [])), RFCSource(rfc_numbers=cfg.get('rfc_numbers', [])), CVESource(cve_ids=cfg.get('cve_ids', [])), NISTSource(publications=cfg.get('nist_publications', [])), CNCFSource(projects=cfg.get('cncf_projects', [])), OWASPSource(projects=cfg.get('owasp_projects', [])), IETFSource(documents=cfg.get('ietf_documents', [])), W3CSource(specs=cfg.get('w3c_specs', [])), ADRSource(adr_urls=cfg.get('adr_urls', []))]
        self.pipeline.register_many(*sources)

    def run_once(self, source_name: str='') -> dict[str, int]:
        if source_name:
            count = self.pipeline.acquire_source(source_name)
            result = {source_name: count}
        else:
            result = self.pipeline.acquire_all()
        now = time.time()
        for name in result:
            self._last_run[name] = now
        self._update_stats(result)
        self._save_state()
        return result

    def _update_stats(self, results: dict[str, int]):
        for name, count in results.items():
            if name not in self._stats:
                self._stats[name] = {'total_items': 0, 'total_runs': 0, 'last_count': 0, 'error_count': 0}
            self._stats[name]['total_items'] += count
            self._stats[name]['total_runs'] += 1
            self._stats[name]['last_count'] = count
            if count == 0:
                self._stats[name]['error_count'] += 1

    def run_all(self) -> dict[str, int]:
        return self.run_once()

    def get_last_run(self, source: str) -> float:
        return self._last_run.get(source, 0.0)

    def get_stats(self) -> dict[str, Any]:
        return dict(self._stats)

    def summary(self) -> dict[str, Any]:
        return {'pipeline': self.pipeline.summary(), 'stats': self._stats, 'last_run_count': len(self._last_run), 'sources_last_run': {k: time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(v)) for k, v in self._last_run.items()}}

    def _save_state(self):
        state = {'last_run': self._last_run, 'stats': self._stats, 'updated_at': time.time()}
        path = self.persistence_dir / 'orchestrator_state.json'
        try:
            path.write_text(json.dumps(state, indent=2, default=str))
        except Exception:
            pass

    def load_state(self):
        path = self.persistence_dir / 'orchestrator_state.json'
        if path.exists():
            try:
                state = json.loads(path.read_text())
                self._last_run = state.get('last_run', {})
                self._stats = state.get('stats', {})
            except Exception:
                pass

