    """Apply confidence decay over time."""
    if self.decay_rate <= 0:
        return
    decay_factor = math.exp(-self.decay_rate * days_passed)
    self.confidence *= decay_factor
    if self.confidence < 0.01:
        self.status = BeliefStatus.UNKNOWN

