class Orchestrator:
    """Multi-agent orchestration for complex task decomposition and execution.

    Supports:
    - Agent registration and capability-based assignment
    - Recursive task decomposition (parent tasks → sub-tasks)
    - Priority-based scheduling
    - Failure detection and retry
    - Hierarchical agent teams
    """

    def __init__(self):
        self._agents: dict[str, CognitiveAgent] = {}
        self._tasks: dict[str, AgentTask] = {}
        self._pending_queue: list[str] = []
        self._completion_handlers: dict[str, list[Callable]] = {}

    @property
    def agent_count(self) -> int:
        return len(self._agents)

    @property
    def task_count(self) -> int:
        return len(self._tasks)

    def register_agent(self, name: str, agent_type: str='', capabilities: list[str] | None=None, parent_id: str='') -> CognitiveAgent:
        agent = CognitiveAgent(name=name, agent_type=agent_type, capabilities=capabilities or [], parent_agent_id=parent_id)
        self._agents[agent.id] = agent
        if parent_id and parent_id in self._agents:
            parent = self._agents[parent_id]
            if agent.id not in parent.child_agent_ids:
                parent.child_agent_ids.append(agent.id)
        return agent

    def find_agents(self, capability: str='', status: AgentStatus | None=None) -> list[CognitiveAgent]:
        results = list(self._agents.values())
        if capability:
            results = [a for a in results if capability in a.capabilities]
        if status:
            results = [a for a in results if a.status == status]
        return results

    def assign_task(self, description: str, required_capabilities: list[str] | None=None, priority: int=5, parent_task_id: str='') -> AgentTask | None:
        """Find the best agent for a task and assign it."""
        capabilities = required_capabilities or []
        available = self.find_agents(status=AgentStatus.IDLE)
        if not capabilities:
            candidates = available
        else:
            candidates = [a for a in available if any((c in a.capabilities for c in capabilities))]
        if not candidates:
            return None
        agent = min(candidates, key=lambda a: len(a.task_history))
        task = AgentTask(description=description, agent_id=agent.id, parent_task_id=parent_task_id, required_capabilities=capabilities, priority=priority)
        self._tasks[task.id] = task
        agent.status = AgentStatus.BUSY
        agent.current_task_id = task.id
        agent.task_history.append(task.id)
        task.status = TaskStatus.ASSIGNED
        task.started_at = time.time()
        return task

    def decompose_task(self, task_id: str, subtasks: list[dict[str, Any]]) -> list[AgentTask]:
        """Decompose a task into sub-tasks and assign them."""
        parent = self._tasks.get(task_id)
        if not parent:
            return []
        children: list[AgentTask] = []
        for st in subtasks:
            child = self.assign_task(description=st.get('description', ''), required_capabilities=st.get('capabilities'), priority=st.get('priority', parent.priority), parent_task_id=task_id)
            if child:
                children.append(child)
                parent.sub_task_ids.append(child.id)
        if children:
            parent.status = TaskStatus.IN_PROGRESS
        return children

    def complete_task(self, task_id: str, result: Any=None):
        """Mark a task as completed."""
        task = self._tasks.get(task_id)
        if not task:
            return
        task.status = TaskStatus.COMPLETED
        task.result = result
        task.completed_at = time.time()
        agent = self._agents.get(task.agent_id)
        if agent:
            agent.status = AgentStatus.IDLE
            agent.current_task_id = ''
        for handler in self._completion_handlers.get(task_id, []):
            handler(task)
        if task.parent_task_id:
            self._check_parent_completion(task.parent_task_id)

    def fail_task(self, task_id: str, error: str=''):
        """Mark a task as failed, with optional retry."""
        task = self._tasks.get(task_id)
        if not task:
            return
        task.error = error
        task.retry_count += 1
        if task.retry_count < task.max_retries:
            agent = self._agents.get(task.agent_id)
            if agent:
                agent.status = AgentStatus.IDLE
                agent.current_task_id = ''
            task.status = TaskStatus.PENDING
            self._pending_queue.append(task.id)
        else:
            task.status = TaskStatus.FAILED
            agent = self._agents.get(task.agent_id)
            if agent:
                agent.status = AgentStatus.ERROR
                agent.current_task_id = ''

    def _check_parent_completion(self, parent_id: str):
        """Check if all sub-tasks of a parent are complete."""
        parent = self._tasks.get(parent_id)
        if not parent:
            return
        all_complete = all((self._tasks.get(sid) and self._tasks[sid].status == TaskStatus.COMPLETED for sid in parent.sub_task_ids)) if parent.sub_task_ids else False
        if all_complete:
            parent.status = TaskStatus.COMPLETED
            parent.completed_at = time.time()

    def on_complete(self, task_id: str, handler: Callable):
        """Register a handler for task completion."""
        self._completion_handlers.setdefault(task_id, []).append(handler)

    def get_agent_tree(self, agent_id: str) -> dict[str, Any]:
        """Get hierarchical agent tree rooted at the given agent."""
        agent = self._agents.get(agent_id)
        if not agent:
            return {}
        return {'id': agent.id, 'name': agent.name, 'type': agent.agent_type, 'status': agent.status.value, 'children': [self.get_agent_tree(cid) for cid in agent.child_agent_ids]}

    def summary(self) -> dict[str, Any]:
        status_counts: dict[str, int] = {}
        for a in self._agents.values():
            status_counts[a.status.value] = status_counts.get(a.status.value, 0) + 1
        task_status: dict[str, int] = {}
        for t in self._tasks.values():
            task_status[t.status.value] = task_status.get(t.status.value, 0) + 1
        return {'agents': {'total': len(self._agents), 'by_status': status_counts}, 'tasks': {'total': len(self._tasks), 'by_status': task_status, 'pending_queue': len(self._pending_queue)}, 'agent_types': {t: len([a for a in self._agents.values() if a.agent_type == t]) for t in set((a.agent_type for a in self._agents.values()))}}

def decompose_task(self, task_id: str, subtasks: list[dict[str, Any]]) -> list[AgentTask]:
    """Decompose a task into sub-tasks and assign them."""
    parent = self._tasks.get(task_id)
    if not parent:
        return []
    children: list[AgentTask] = []
    for st in subtasks:
        child = self.assign_task(description=st.get('description', ''), required_capabilities=st.get('capabilities'), priority=st.get('priority', parent.priority), parent_task_id=task_id)
        if child:
            children.append(child)
            parent.sub_task_ids.append(child.id)
    if children:
        parent.status = TaskStatus.IN_PROGRESS
    return children

def complete_task(self, task_id: str, result: Any=None):
    """Mark a task as completed."""
    task = self._tasks.get(task_id)
    if not task:
        return
    task.status = TaskStatus.COMPLETED
    task.result = result
    task.completed_at = time.time()
    agent = self._agents.get(task.agent_id)
    if agent:
        agent.status = AgentStatus.IDLE
        agent.current_task_id = ''
    for handler in self._completion_handlers.get(task_id, []):
        handler(task)
    if task.parent_task_id:
        self._check_parent_completion(task.parent_task_id)

def fail_task(self, task_id: str, error: str=''):
    """Mark a task as failed, with optional retry."""
    task = self._tasks.get(task_id)
    if not task:
        return
    task.error = error
    task.retry_count += 1
    if task.retry_count < task.max_retries:
        agent = self._agents.get(task.agent_id)
        if agent:
            agent.status = AgentStatus.IDLE
            agent.current_task_id = ''
        task.status = TaskStatus.PENDING
        self._pending_queue.append(task.id)
    else:
        task.status = TaskStatus.FAILED
        agent = self._agents.get(task.agent_id)
        if agent:
            agent.status = AgentStatus.ERROR
            agent.current_task_id = ''

def _check_parent_completion(self, parent_id: str):
    """Check if all sub-tasks of a parent are complete."""
    parent = self._tasks.get(parent_id)
    if not parent:
        return
    all_complete = all((self._tasks.get(sid) and self._tasks[sid].status == TaskStatus.COMPLETED for sid in parent.sub_task_ids)) if parent.sub_task_ids else False
    if all_complete:
        parent.status = TaskStatus.COMPLETED
        parent.completed_at = time.time()

def on_complete(self, task_id: str, handler: Callable):
    """Register a handler for task completion."""
    self._completion_handlers.setdefault(task_id, []).append(handler)

def get_agent_tree(self, agent_id: str) -> dict[str, Any]:
    """Get hierarchical agent tree rooted at the given agent."""
    agent = self._agents.get(agent_id)
    if not agent:
        return {}
    return {'id': agent.id, 'name': agent.name, 'type': agent.agent_type, 'status': agent.status.value, 'children': [self.get_agent_tree(cid) for cid in agent.child_agent_ids]}

class ReasoningEngine:
    """Multi-modal reasoning over beliefs, entities, and causal graphs.

    Supports causal inference, counterfactual reasoning, Bayesian updates,
    and deductive/inductive/abductive/analogical inference.
    """

    def __init__(self):
        self._causal_links: dict[str, CausalLink] = {}
        self._inferences: list[Inference] = []
        self._rules: list[tuple[str, str, float]] = []

    @property
    def inference_count(self) -> int:
        return len(self._inferences)

    @property
    def causal_link_count(self) -> int:
        return len(self._causal_links)

    def add_causal_link(self, source_id: str, target_id: str, strength: float=0.5, direction: str='forward', **metadata) -> CausalLink:
        key = f'{source_id}→{target_id}'
        existing = self._causal_links.get(key)
        if existing:
            existing.evidence_count += 1
            existing.strength = (existing.strength + strength) / 2
            existing.metadata.update(metadata)
            return existing
        link = CausalLink(source_id=source_id, target_id=target_id, strength=strength, direction=direction, metadata=metadata)
        self._causal_links[key] = link
        return link

    def infer_causes(self, target_id: str, min_strength: float=0.1) -> list[CausalLink]:
        """Find all causal links pointing to a target."""
        return [l for l in self._causal_links.values() if l.target_id == target_id and l.strength >= min_strength]

    def infer_effects(self, source_id: str, min_strength: float=0.1) -> list[CausalLink]:
        """Find all causal links originating from a source."""
        return [l for l in self._causal_links.values() if l.source_id == source_id and l.strength >= min_strength]

    def causal_chain(self, start_id: str, max_depth: int=5) -> list[list[CausalLink]]:
        """Trace causal chains forward from a starting entity."""
        chains: list[list[CausalLink]] = []

        def _trace(current_id: str, path: list[CausalLink], depth: int):
            if depth > max_depth:
                return
            effects = self.infer_effects(current_id)
            if not effects:
                if path:
                    chains.append(list(path))
                return
            for effect in effects:
                path.append(effect)
                _trace(effect.target_id, path, depth + 1)
                path.pop()
        _trace(start_id, [], 0)
        return chains

    def counterfactual(self, belief_fn: Callable[[str], float], what_if: str, new_value: float) -> dict[str, float]:
        """What-if analysis: change a variable and observe effects.

        Args:
            belief_fn: Function that returns confidence for a given entity ID
            what_if: Entity ID to change
            new_value: New confidence/value for the entity

        Returns:
            Dict mapping affected entity IDs → their new inferred confidence
        """
        effects: dict[str, float] = {}
        effects[what_if] = new_value
        queue = [(what_if, 1.0)]
        visited = {what_if}
        while queue:
            current, decay = queue.pop(0)
            links = self.infer_effects(current)
            for link in links:
                if link.target_id not in visited:
                    visited.add(link.target_id)
                    propagated = new_value * link.strength * decay
                    effects[link.target_id] = propagated
                    queue.append((link.target_id, decay * 0.5))
        return effects

    def bayesian_update(self, prior: float, likelihood: float, evidence_prob: float) -> float:
        """P(H|E) = P(E|H) * P(H) / P(E)

        Args:
            prior: P(H) — prior probability of hypothesis
            likelihood: P(E|H) — probability of evidence given hypothesis
            evidence_prob: P(E) — probability of evidence

        Returns:
            P(H|E) — posterior probability
        """
        if evidence_prob == 0:
            return prior
        return likelihood * prior / evidence_prob

    def bayesian_network(self, priors: dict[str, float], conditional: dict[str, dict[str, float]]) -> dict[str, float]:
        """Simple Bayesian network inference.

        Args:
            priors: Dict mapping node_id → prior probability
            conditional: Dict mapping node_id → {parent_value: conditional_prob}

        Returns:
            Dict mapping node_id → posterior probability
        """
        posteriors = dict(priors)
        for node_id, conds in conditional.items():
            if node_id in priors:
                continue
            posterior = 0.0
            for parent_val, cond_prob in conds.items():
                parent_prob = posteriors.get(parent_val, 0.5)
                posterior += parent_prob * cond_prob
            posteriors[node_id] = min(1.0, posterior)
        return posteriors

    def add_rule(self, antecedent: str, consequent: str, confidence: float=1.0):
        """Add a deductive rule: if antecedent then consequent."""
        self._rules.append((antecedent, consequent, confidence))

    def deduce(self, facts: dict[str, float], min_confidence: float=0.1) -> list[Inference]:
        """Apply rules to facts to derive new conclusions."""
        inferences: list[Inference] = []
        for antecedent, consequent, rule_conf in self._rules:
            for fact_name, fact_conf in facts.items():
                if antecedent.lower() in fact_name.lower() or fact_name.lower() in antecedent.lower():
                    confidence = fact_conf * rule_conf
                    if confidence >= min_confidence:
                        inference = Inference(premise=f'{antecedent} (confidence: {fact_conf})', conclusion=consequent, confidence=confidence, mode=ReasoningMode.DEDUCTIVE, source_ids=[fact_name])
                        inferences.append(inference)
                        self._inferences.append(inference)
        return inferences

    def analogical_transfer(self, source_entity: dict[str, Any], target_entity: dict[str, Any], similarity_fn: Callable[[dict, dict], float]) -> list[str]:
        """Transfer attributes from source to target based on similarity."""
        similarity = similarity_fn(source_entity, target_entity)
        if similarity < 0.3:
            return []
        transferred: list[str] = []
        for key, value in source_entity.items():
            if key not in target_entity or target_entity[key] is None:
                transferred.append(key)
        return transferred

    def summary(self) -> dict[str, Any]:
        return {'total_inferences': len(self._inferences), 'causal_links': len(self._causal_links), 'rules': len(self._rules), 'by_mode': {mode.value: len([i for i in self._inferences if i.mode == mode]) for mode in ReasoningMode}}

