                findings.append(ResearchFinding(id=generate_id('sec', 12), title=f"Security mechanism: {sp['category']}", description=f"Detected {sp.get('evidence_count', 0)} instances of {sp['category']}", evidence=f"Confidence: {sp.get('confidence', 0.5):.2f}", confidence=sp.get('confidence', 0.5), impact=0.4, tags=['security', sp['category']]))
        repo_path = context.get('repo_path')
        if repo_path:
            path = Path(repo_path)
            secrets = self._scan_secrets(path)
            if secrets:
                findings.append(ResearchFinding(id=generate_id('sec', 12), title=f'Potential secrets: {len(secrets)}', description=f'Files with potential secrets: {secrets[:5]}', evidence='Detected using pattern matching', confidence=0.5, impact=-0.7, tags=['security', 'secrets', 'risk']))
        return findings

    def generate_questions(self, context: dict[str, Any]) -> list[ResearchQuestion]:
        return [ResearchQuestion(question='What is the security posture of this repository?', hypothesis='Repos with auth, encryption, and validation have fewer vulnerabilities', priority=0.8, status='open', created_at=time.time()), ResearchQuestion(question='Are there hardcoded secrets?', hypothesis='Secret keys in source code are the most common security risk', priority=0.9, status='open', created_at=time.time())]

    def _scan_secrets(self, path: Path) -> list[str]:
        secret_patterns = ['SECRET_KEY\\s*=\\s*["\\\'][^"\\\']+["\\\']', 'API_KEY\\s*=\\s*["\\\'][^"\\\']+["\\\']', 'PASSWORD\\s*=\\s*["\\\'][^"\\\']+["\\\']', 'api_key\\s*=\\s*["\\\'][^"\\\']+["\\\']', 'password\\s*=\\s*["\\\'][^"\\\']+["\\\']']
        hits = []
        for f in path.rglob('*.py'):
            try:
                text = f.read_text(errors='replace')
                for pat in secret_patterns:
                    if re.search(pat, text):
                        hits.append(str(f.relative_to(path)))
                        break
            except Exception:
                continue
        return hits

