            assert_count = sum((1 for g in genome.all_genes if 'assert' in (g.name or '').lower()))
            if genome.gene_count > 0:
                assert_density = assert_count / genome.gene_count
                if assert_density < 0.02:
                    findings.append(ResearchFinding(id=generate_id('formal', 12), title=f'Low assertion density: {assert_density:.2%}', description=f'Only {assert_count} assertions across {genome.gene_count} genes', evidence='Low assertion density indicates weak runtime verification', confidence=0.6, impact=-0.3, tags=['formal', 'assertions', 'quality']))
        if twin:
            if hasattr(twin, 'verify_invariant'):
                try:
                    result = twin.verify_invariant()
                    if result:
                        findings.append(ResearchFinding(id=generate_id('formal', 12), title=f'Architecture invariants: {len(result)}', description=f'Architecture invariant verification produced {len(result)} results', evidence=str(result)[:200], confidence=0.7, impact=0.4, tags=['formal', 'invariants', 'architecture']))
                except Exception:
                    pass
        return findings

    def generate_questions(self, context: dict[str, Any]) -> list[ResearchQuestion]:
        return [ResearchQuestion(question='Can architecture invariants be verified automatically?', hypothesis='Layer constraints and import rules form a checkable invariant set', priority=0.9, status='open', created_at=time.time()), ResearchQuestion(question='What is the formal specification coverage?', hypothesis='Specification coverage below 10% means most behavior is unverified', priority=0.8, status='open', created_at=time.time())]

@dataclass
class ResearchFinding:
