class WorkingMemory:
    """Limited-capacity working memory with salience-based eviction.

    Capacity defaults to 7 ± 2 items (Miller's Law).
    Items with lowest salience are evicted when capacity is exceeded.
    """

    def __init__(self, capacity: int=7):
        self._slots: dict[str, WorkingMemorySlot] = {}
        self._capacity = capacity
        self._eviction_count = 0

    @property
    def size(self) -> int:
        return len(self._slots)

    @property
    def capacity(self) -> int:
        return self._capacity

    @property
    def utilization(self) -> float:
        return len(self._slots) / self._capacity

    def store(self, content: str, content_type: str='text', source: str='', salience: float=0.5, **metadata) -> WorkingMemorySlot:
        slot = WorkingMemorySlot(content=content, content_type=content_type, source=source, salience=salience, metadata=metadata)
        self._slots[slot.id] = slot
        self._evict_if_needed()
        return slot

    def get(self, slot_id: str) -> WorkingMemorySlot | None:
        slot = self._slots.get(slot_id)
        if slot:
            slot.last_accessed = time.time()
            slot.access_count += 1
        return slot

    def retrieve(self, content_contains: str='', content_type: str='', min_salience: float=0.0) -> list[WorkingMemorySlot]:
        results = list(self._slots.values())
        if content_contains:
            results = [s for s in results if content_contains.lower() in s.content.lower()]
        if content_type:
            results = [s for s in results if s.content_type == content_type]
        if min_salience > 0:
            results = [s for s in results if s.salience >= min_salience]
        return sorted(results, key=lambda s: s.salience, reverse=True)

    def focus(self) -> WorkingMemorySlot | None:
        """Return the highest-salience item (attention focus)."""
        if not self._slots:
            return None
        return max(self._slots.values(), key=lambda s: s.salience)

    def update_salience(self, slot_id: str, delta: float):
        """Increase or decrease salience of a working memory item."""
        slot = self._slots.get(slot_id)
        if slot:
            slot.salience = max(0.0, min(1.0, slot.salience + delta))

    def decay_all(self, rate: float=0.1):
        """Decay salience of all items."""
        for slot in list(self._slots.values()):
            slot.salience = max(0.0, slot.salience - rate)
            if slot.salience <= 0:
                del self._slots[slot.id]
                self._eviction_count += 1

    def clear(self):
        self._slots.clear()

    def _evict_if_needed(self):
        while len(self._slots) > self._capacity:
            lowest = min(self._slots.values(), key=lambda s: s.salience)
            del self._slots[lowest.id]
            self._eviction_count += 1

    def summary(self) -> dict[str, Any]:
        types: dict[str, int] = {}
        for s in self._slots.values():
            types[s.content_type] = types.get(s.content_type, 0) + 1
        return {'size': self.size, 'capacity': self._capacity, 'utilization': round(self.utilization, 2), 'by_type': types, 'eviction_count': self._eviction_count, 'focus': self.focus().content if self.focus() else None}

class EpisodicMemory:
    """Episodic memory — stores and retrieves timestamped cognitive episodes.

    Supports retrieval by:
    - Recency (most recent events first)
    - Relevance (matching entity IDs or tags)
    - Importance threshold
    - Pattern matching (events of a specific type)
    """

    def __init__(self, max_entries: int=10000):
        self._entries: list[EpisodicMemoryEntry] = []
        self._max_entries = max_entries
        self._index_by_type: dict[str, list[int]] = defaultdict(list)
        self._index_by_entity: dict[str, list[int]] = defaultdict(list)

    @property
    def entry_count(self) -> int:
        return len(self._entries)

    def record(self, event_type: str, description: str, entities: list[str] | None=None, beliefs_before: dict[str, float] | None=None, beliefs_after: dict[str, float] | None=None, outcome: str='unknown', importance: float=0.5, tags: list[str] | None=None, **metadata) -> EpisodicMemoryEntry:
        entry = EpisodicMemoryEntry(event_type=event_type, description=description, entities=entities or [], beliefs_before=beliefs_before or {}, beliefs_after=beliefs_after or {}, outcome=outcome, importance=importance, tags=tags or [], metadata=metadata)
        idx = len(self._entries)
        self._entries.append(entry)
        self._index_by_type[entry.event_type].append(idx)
        for eid in entry.entities:
            self._index_by_entity[eid].append(idx)
        if len(self._entries) > self._max_entries:
            excess = len(self._entries) - self._max_entries
            self._entries = self._entries[excess:]
            self._rebuild_indexes()
        return entry

    def recent(self, limit: int=10) -> list[EpisodicMemoryEntry]:
        """Most recent episodes."""
        return list(reversed(self._entries[-limit:]))

    def by_type(self, event_type: str, limit: int=20) -> list[EpisodicMemoryEntry]:
        indices = self._index_by_type.get(event_type, [])
        entries = [self._entries[i] for i in indices if i < len(self._entries)]
        return list(reversed(entries))[:limit]

    def by_entity(self, entity_id: str, limit: int=20) -> list[EpisodicMemoryEntry]:
        indices = self._index_by_entity.get(entity_id, [])
        entries = [self._entries[i] for i in indices if i < len(self._entries)]
        return list(reversed(entries))[:limit]

    def search(self, query: str='', min_importance: float=0.0, limit: int=20) -> list[EpisodicMemoryEntry]:
        results: list[EpisodicMemoryEntry] = []
        for entry in reversed(self._entries):
            if len(results) >= limit:
                break
            if entry.importance < min_importance:
                continue
            if query and query.lower() not in entry.description.lower():
                continue
            results.append(entry)
        return results

    def replay(self, event_type: str) -> list[dict[str, Any]]:
        """Replay all episodes of a given type — useful for reflection."""
        entries = self.by_type(event_type)
        return [{'timestamp': e.timestamp, 'description': e.description, 'outcome': e.outcome, 'beliefs_before': e.beliefs_before, 'beliefs_after': e.beliefs_after} for e in entries]

    def _rebuild_indexes(self):
        self._index_by_type.clear()
        self._index_by_entity.clear()
        for i, entry in enumerate(self._entries):
            self._index_by_type[entry.event_type].append(i)
            for eid in entry.entities:
                self._index_by_entity[eid].append(i)

    def summary(self) -> dict[str, Any]:
        type_counts: dict[str, int] = {}
        for e in self._entries:
            type_counts[e.event_type] = type_counts.get(e.event_type, 0) + 1
        return {'total_entries': len(self._entries), 'max_entries': self._max_entries, 'by_type': type_counts, 'recent_outcomes': [e.outcome for e in self._entries[-5:]]}

def focus(self) -> WorkingMemorySlot | None:
    """Return the highest-salience item (attention focus)."""
    if not self._slots:
        return None
    return max(self._slots.values(), key=lambda s: s.salience)

def update_salience(self, slot_id: str, delta: float):
    """Increase or decrease salience of a working memory item."""
    slot = self._slots.get(slot_id)
    if slot:
        slot.salience = max(0.0, min(1.0, slot.salience + delta))

def decay_all(self, rate: float=0.1):
    """Decay salience of all items."""
    for slot in list(self._slots.values()):
        slot.salience = max(0.0, slot.salience - rate)
        if slot.salience <= 0:
            del self._slots[slot.id]
            self._eviction_count += 1

def recent(self, limit: int=10) -> list[EpisodicMemoryEntry]:
    """Most recent episodes."""
    return list(reversed(self._entries[-limit:]))

@dataclass
class CognitiveAgent:
    """An agent in the cognitive architecture."""
    id: str = ''
    name: str = ''
    agent_type: str = ''
    capabilities: list[str] = field(default_factory=list)
    status: AgentStatus = AgentStatus.IDLE
    current_task_id: str = ''
    task_history: list[str] = field(default_factory=list)
    parent_agent_id: str = ''
    child_agent_ids: list[str] = field(default_factory=list)
    metadata: dict[str, Any] = field(default_factory=dict)
    created_at: float = 0.0

    def __post_init__(self):
        if not self.id:
            self.id = generate_id('agent', 10)
        if not self.created_at:
            self.created_at = time.time()

    @property
    def is_available(self) -> bool:
        return self.status == AgentStatus.IDLE

    def to_dict(self) -> dict[str, Any]:
        return {'id': self.id, 'name': self.name, 'agent_type': self.agent_type, 'capabilities': self.capabilities, 'status': self.status.value, 'current_task_id': self.current_task_id, 'parent_agent_id': self.parent_agent_id, 'child_agent_ids': self.child_agent_ids}

class Orchestrator:
    """Multi-agent orchestration for complex task decomposition and execution.

    Supports:
    - Agent registration and capability-based assignment
    - Recursive task decomposition (parent tasks → sub-tasks)
    - Priority-based scheduling
    - Failure detection and retry
    - Hierarchical agent teams
    """

    def __init__(self):
        self._agents: dict[str, CognitiveAgent] = {}
        self._tasks: dict[str, AgentTask] = {}
        self._pending_queue: list[str] = []
        self._completion_handlers: dict[str, list[Callable]] = {}

    @property
    def agent_count(self) -> int:
        return len(self._agents)

    @property
    def task_count(self) -> int:
        return len(self._tasks)

    def register_agent(self, name: str, agent_type: str='', capabilities: list[str] | None=None, parent_id: str='') -> CognitiveAgent:
        agent = CognitiveAgent(name=name, agent_type=agent_type, capabilities=capabilities or [], parent_agent_id=parent_id)
        self._agents[agent.id] = agent
        if parent_id and parent_id in self._agents:
            parent = self._agents[parent_id]
            if agent.id not in parent.child_agent_ids:
                parent.child_agent_ids.append(agent.id)
        return agent

    def find_agents(self, capability: str='', status: AgentStatus | None=None) -> list[CognitiveAgent]:
        results = list(self._agents.values())
        if capability:
            results = [a for a in results if capability in a.capabilities]
        if status:
            results = [a for a in results if a.status == status]
        return results

    def assign_task(self, description: str, required_capabilities: list[str] | None=None, priority: int=5, parent_task_id: str='') -> AgentTask | None:
        """Find the best agent for a task and assign it."""
        capabilities = required_capabilities or []
        available = self.find_agents(status=AgentStatus.IDLE)
        if not capabilities:
            candidates = available
        else:
            candidates = [a for a in available if any((c in a.capabilities for c in capabilities))]
        if not candidates:
            return None
        agent = min(candidates, key=lambda a: len(a.task_history))
        task = AgentTask(description=description, agent_id=agent.id, parent_task_id=parent_task_id, required_capabilities=capabilities, priority=priority)
        self._tasks[task.id] = task
        agent.status = AgentStatus.BUSY
        agent.current_task_id = task.id
        agent.task_history.append(task.id)
        task.status = TaskStatus.ASSIGNED
        task.started_at = time.time()
        return task

    def decompose_task(self, task_id: str, subtasks: list[dict[str, Any]]) -> list[AgentTask]:
        """Decompose a task into sub-tasks and assign them."""
        parent = self._tasks.get(task_id)
        if not parent:
            return []
        children: list[AgentTask] = []
        for st in subtasks:
            child = self.assign_task(description=st.get('description', ''), required_capabilities=st.get('capabilities'), priority=st.get('priority', parent.priority), parent_task_id=task_id)
            if child:
                children.append(child)
                parent.sub_task_ids.append(child.id)
        if children:
            parent.status = TaskStatus.IN_PROGRESS
        return children

    def complete_task(self, task_id: str, result: Any=None):
        """Mark a task as completed."""
        task = self._tasks.get(task_id)
        if not task:
            return
        task.status = TaskStatus.COMPLETED
        task.result = result
        task.completed_at = time.time()
        agent = self._agents.get(task.agent_id)
        if agent:
            agent.status = AgentStatus.IDLE
            agent.current_task_id = ''
        for handler in self._completion_handlers.get(task_id, []):
            handler(task)
        if task.parent_task_id:
            self._check_parent_completion(task.parent_task_id)

    def fail_task(self, task_id: str, error: str=''):
        """Mark a task as failed, with optional retry."""
        task = self._tasks.get(task_id)
        if not task:
            return
        task.error = error
        task.retry_count += 1
        if task.retry_count < task.max_retries:
            agent = self._agents.get(task.agent_id)
            if agent:
                agent.status = AgentStatus.IDLE
                agent.current_task_id = ''
            task.status = TaskStatus.PENDING
            self._pending_queue.append(task.id)
        else:
            task.status = TaskStatus.FAILED
            agent = self._agents.get(task.agent_id)
            if agent:
                agent.status = AgentStatus.ERROR
                agent.current_task_id = ''

    def _check_parent_completion(self, parent_id: str):
        """Check if all sub-tasks of a parent are complete."""
        parent = self._tasks.get(parent_id)
        if not parent:
            return
        all_complete = all((self._tasks.get(sid) and self._tasks[sid].status == TaskStatus.COMPLETED for sid in parent.sub_task_ids)) if parent.sub_task_ids else False
        if all_complete:
            parent.status = TaskStatus.COMPLETED
            parent.completed_at = time.time()

    def on_complete(self, task_id: str, handler: Callable):
        """Register a handler for task completion."""
        self._completion_handlers.setdefault(task_id, []).append(handler)

    def get_agent_tree(self, agent_id: str) -> dict[str, Any]:
        """Get hierarchical agent tree rooted at the given agent."""
        agent = self._agents.get(agent_id)
        if not agent:
            return {}
        return {'id': agent.id, 'name': agent.name, 'type': agent.agent_type, 'status': agent.status.value, 'children': [self.get_agent_tree(cid) for cid in agent.child_agent_ids]}

    def summary(self) -> dict[str, Any]:
        status_counts: dict[str, int] = {}
        for a in self._agents.values():
            status_counts[a.status.value] = status_counts.get(a.status.value, 0) + 1
        task_status: dict[str, int] = {}
        for t in self._tasks.values():
            task_status[t.status.value] = task_status.get(t.status.value, 0) + 1
        return {'agents': {'total': len(self._agents), 'by_status': status_counts}, 'tasks': {'total': len(self._tasks), 'by_status': task_status, 'pending_queue': len(self._pending_queue)}, 'agent_types': {t: len([a for a in self._agents.values() if a.agent_type == t]) for t in set((a.agent_type for a in self._agents.values()))}}

def decompose_task(self, task_id: str, subtasks: list[dict[str, Any]]) -> list[AgentTask]:
    """Decompose a task into sub-tasks and assign them."""
    parent = self._tasks.get(task_id)
    if not parent:
        return []
    children: list[AgentTask] = []
    for st in subtasks:
        child = self.assign_task(description=st.get('description', ''), required_capabilities=st.get('capabilities'), priority=st.get('priority', parent.priority), parent_task_id=task_id)
        if child:
            children.append(child)
            parent.sub_task_ids.append(child.id)
    if children:
        parent.status = TaskStatus.IN_PROGRESS
    return children

def complete_task(self, task_id: str, result: Any=None):
    """Mark a task as completed."""
    task = self._tasks.get(task_id)
