    def type_label(self) -> str:
        return f'{self.entity_type}:{self.label or self.brain_id}'

    def add_relationship(self, target_id: str, relation: str='references', weight: float=1.0, label: str='', **metadata) -> Relationship:
        rel = Relationship(target_id=target_id, relation=relation, weight=weight, label=label, metadata=metadata)
        self.relationships.append(rel)
        return rel

    def find_relationships(self, relation: str | None=None, target_id: str | None=None) -> list[Relationship]:
        results = []
        for r in self.relationships:
            if relation and r.relation != relation:
                continue
            if target_id and r.target_id != target_id:
                continue
            results.append(r)
        return results

