        core_caps = [('compiler', 'Multi-source compiler framework', '1.0.0'), ('parser', 'Multi-format source parser', '1.0.0'), ('validator', 'Universal validation engine', '1.0.0'), ('knowledge_graph', 'Knowledge graph engine', '1.0.0'), ('metadata_engine', 'Automatic metadata management', '1.0.0'), ('type_registry', 'Semantic type registry', '1.0.0'), ('plugin_manager', 'Plugin installation and lifecycle', '1.0.0'), ('capability_registry', 'Capability registration and discovery', '1.0.0'), ('repository_indexer', 'Repository scanning and indexing', '1.0.0'), ('execution_engine', 'DAG-based workflow execution', '1.0.0'), ('package_manager', 'VenusPM package management', '1.0.0'), ('studio_backend', 'Venus Studio backend APIs', '1.0.0'), ('diagnostics', 'Self-diagnostics and health checks', '1.0.0'), ('memory_engine', 'Institutional memory management', '1.0.0'), ('graph_exporter', 'Graph export to Neo4j and other formats', '1.0.0'), ('project_manager', 'Project management and lifecycle', '1.0.0'), ('certification', 'Artifact certification', '1.0.0'), ('security', 'Security validation and policies', '1.0.0')]
