def find_test_file(module_path: str, package: str) -> str | None:
    """Map a source module to its test file."""
    rel = module_path.replace(f'{package}/', '').replace('.py', '')
    candidate = TEST_DIR / f"test_{rel.split('/')[-1]}.py"
    if candidate.exists():
        return str(candidate.relative_to(REPO_ROOT))
    candidate2 = TEST_DIR / f"test_{package.split('.')[-1]}.py"
    if candidate2.exists():
        return str(candidate2.relative_to(REPO_ROOT))
    return None

def build_enhanced_census(census_result: dict[str, Any]) -> dict[str, Any]:
    """Run all enhanced entity scanners and merge catalogs."""
    module_catalog = census_result.get('module_catalog', {})
    modules: dict[str, ModuleInfo] = {}
    for key, data in module_catalog.items():
        if isinstance(data, dict):
            mod = ModuleInfo(**{k: v for k, v in data.items() if k in ModuleInfo.__dataclass_fields__})
            modules[key] = mod
    for etype_tag, catalog_key, scanner_fn in ENHANCED_SCANNERS:
        records = scanner_fn(modules)
        census_result[catalog_key] = records
    return census_result

class CertificationEngine:
    """Artifact certification — validates and certifies platform artifacts."""
    CERTIFICATION_LEVELS = ['uncertified', 'bronze', 'silver', 'gold', 'platinum']

    def __init__(self, event_bus: EventBus | None=None, memory_store: MemoryStore | None=None):
        self._bus = event_bus
        self._store = memory_store
        self._certifications: dict[str, dict[str, Any]] = {}
        if self._store is not None:
            for entry in self._store.list_namespace('certifications'):
                data = entry.get('value')
                if data and data.get('artifact_id'):
                    self._certifications[data['artifact_id']] = data

    def _emit(self, event_type: str, data: dict[str, Any] | None=None) -> None:
        if self._bus is not None:
            self._bus.emit(event_type, data or {})

    def certify(self, artifact_id: str, level: str='bronze') -> dict[str, Any] | None:
        if level not in self.CERTIFICATION_LEVELS:
            return None
        record = {'artifact_id': artifact_id, 'level': level, 'certified_at': datetime.now(timezone.utc).isoformat()}
        self._certifications[artifact_id] = record
        if self._store is not None:
            self._store.store('certifications', artifact_id, record)
        self._emit('artifact.certified', record)
        return record

    def revoke(self, artifact_id: str) -> bool:
        if artifact_id in self._certifications:
            del self._certifications[artifact_id]
            if self._store is not None:
                self._store.forget('certifications', artifact_id)
            self._emit('artifact.certification.revoked', {'artifact_id': artifact_id})
            return True
        return False

    def get_certification(self, artifact_id: str) -> dict[str, Any] | None:
        return self._certifications.get(artifact_id)

    def list_by_level(self, level: str) -> list[dict[str, Any]]:
        return [r for r in self._certifications.values() if r.get('level') == level]

class ArchitectureScientist(ResearchAgent):
    """Researcher focused on software architecture, patterns, coupling."""

    def research_domain(self) -> str:
        return 'software_architecture'

    def investigate(self, context: dict[str, Any]) -> list[ResearchFinding]:
        findings = []
        genome = context.get('genome')
        twin = context.get('twin')
        repo_path = context.get('repo_path')
        if genome:
            coupling = genome.fitness.coupling if genome.fitness else 0.0
            maintainability = genome.fitness.maintainability if genome.fitness else 0.0
            chrom_count = genome.chromosome_count
            gene_count = genome.gene_count
            findings.append(ResearchFinding(id=generate_id('arch', 12), title=f'Architectural coupling: {coupling:.4f}', description=f'Repository {genome.repository_name} has coupling {coupling:.4f} ({chrom_count} chromosomes, {gene_count} genes)', evidence=f'Maintainability: {maintainability:.4f}, Species: {genome.species}', confidence=0.8, impact=coupling * 0.5, tags=['architecture', 'coupling', genome.species]))
            findings.append(ResearchFinding(id=generate_id('arch', 12), title=f'Species: {genome.species}', description=f"Classified as '{genome.species}' based on {chrom_count} chromosomes, {genome.total_dependencies} dependencies", evidence=f'Dominant traits: {dict(genome.dominant_traits[:5])}', confidence=0.7, impact=0.3, tags=['species', 'taxonomy', genome.species]))
            if gene_count > 0:
                type_counts: dict[str, int] = {}
                for g in genome.all_genes:
                    type_counts[g.gene_type.name.lower()] = type_counts.get(g.gene_type.name.lower(), 0) + 1
                findings.append(ResearchFinding(id=generate_id('arch', 12), title=f'Gene composition: {len(type_counts)} types', description=f'Gene type distribution: {type_counts}', evidence=f'Total genes: {gene_count}', confidence=0.9, impact=0.2, tags=['composition', 'gene_types']))
        if twin:
            all_edges = []
            if hasattr(twin, 'find_edges'):
                all_edges = twin.find_edges()
            if all_edges:
                hub_modules = self._find_hubs(all_edges)
                if hub_modules:
                    findings.append(ResearchFinding(id=generate_id('arch', 12), title=f'Hubs detected: {len(hub_modules)} modules', description=f'Highly coupled modules: {hub_modules[:5]}', evidence=f'Total edges: {len(all_edges)}', confidence=0.6, impact=-0.3, tags=['hub', 'coupling', 'bottleneck']))
        return findings

    def generate_questions(self, context: dict[str, Any]) -> list[ResearchQuestion]:
        return [ResearchQuestion(question='What is the optimal coupling range for this architecture?', hypothesis='Coupling between 0.3 and 0.7 correlates with highest fitness', priority=0.8, status='open', created_at=time.time()), ResearchQuestion(question='Which modules are architectural bottlenecks?', hypothesis='Modules with >5 incoming dependencies degrade maintainability', priority=0.7, status='open', created_at=time.time()), ResearchQuestion(question='Is there evidence of architectural drift?', hypothesis='Growing module count without layer boundaries indicates drift', priority=0.6, status='open', created_at=time.time())]

    def _find_hubs(self, edges: list, threshold: int=5) -> list[str]:
        targets: dict[str, int] = {}
        for e in edges:
            tgt = e[1] if len(e) > 1 else ''
            targets[tgt] = targets.get(tgt, 0) + 1
        return [m for m, c in sorted(targets.items(), key=lambda x: -x[1]) if c >= threshold][:10]

class SecurityScientist(ResearchAgent):
    """Researcher focused on software security."""

    def research_domain(self) -> str:
        return 'software_security'

    def investigate(self, context: dict[str, Any]) -> list[ResearchFinding]:
        findings = []
        extraction = context.get('extraction')
        if extraction and hasattr(extraction, 'security_policies'):
            for sp in extraction.security_policies:
                findings.append(ResearchFinding(id=generate_id('sec', 12), title=f"Security mechanism: {sp['category']}", description=f"Detected {sp.get('evidence_count', 0)} instances of {sp['category']}", evidence=f"Confidence: {sp.get('confidence', 0.5):.2f}", confidence=sp.get('confidence', 0.5), impact=0.4, tags=['security', sp['category']]))
        repo_path = context.get('repo_path')
        if repo_path:
            path = Path(repo_path)
            secrets = self._scan_secrets(path)
            if secrets:
                findings.append(ResearchFinding(id=generate_id('sec', 12), title=f'Potential secrets: {len(secrets)}', description=f'Files with potential secrets: {secrets[:5]}', evidence='Detected using pattern matching', confidence=0.5, impact=-0.7, tags=['security', 'secrets', 'risk']))
        return findings

    def generate_questions(self, context: dict[str, Any]) -> list[ResearchQuestion]:
        return [ResearchQuestion(question='What is the security posture of this repository?', hypothesis='Repos with auth, encryption, and validation have fewer vulnerabilities', priority=0.8, status='open', created_at=time.time()), ResearchQuestion(question='Are there hardcoded secrets?', hypothesis='Secret keys in source code are the most common security risk', priority=0.9, status='open', created_at=time.time())]

    def _scan_secrets(self, path: Path) -> list[str]:
        secret_patterns = ['SECRET_KEY\\s*=\\s*["\\\'][^"\\\']+["\\\']', 'API_KEY\\s*=\\s*["\\\'][^"\\\']+["\\\']', 'PASSWORD\\s*=\\s*["\\\'][^"\\\']+["\\\']', 'api_key\\s*=\\s*["\\\'][^"\\\']+["\\\']', 'password\\s*=\\s*["\\\'][^"\\\']+["\\\']']
        hits = []
        for f in path.rglob('*.py'):
            try:
                text = f.read_text(errors='replace')
                for pat in secret_patterns:
                    if re.search(pat, text):
                        hits.append(str(f.relative_to(path)))
                        break
            except Exception:
                continue
        return hits

