class AutonomousEngine:
    """The complete autonomous engineering cycle — Observe → ... → Learn → Repeat."""

    def __init__(self):
        self._handlers: dict[CycleStage, Callable] = {}
        self._history: list[CycleRun] = []
        self._lock = RLock()
        self._running = False

    def register(self, stage: CycleStage, handler: Callable):
        self._handlers[stage] = handler

    def run(self, initial_context: dict[str, Any] | None=None) -> CycleRun:
        run = CycleRun(context=dict(initial_context or {}))
        with self._lock:
            self._history.append(run)
        for stage in CYCLE_ORDER:
            handler = self._handlers.get(stage)
            result = CycleResult(stage=stage, started_at=time.time())
            if handler:
                try:
                    output = handler(run.context)
                    result.output = output if isinstance(output, dict) else {'result': output}
                    result.status = 'completed'
                except Exception as e:
                    result.status = 'failed'
                    result.errors = [str(e)]
                    run.status = 'failed'
                    run.error = str(e)
            else:
                result.status = 'skipped'
            result.completed_at = time.time()
            run.results[stage.value] = result
            if result.status == 'failed':
                break
        run.status = 'completed' if run.status != 'failed' else 'failed'
        run.completed_at = time.time()
        run.metrics = self._compute_metrics(run)
        return run

    def run_continuous(self, interval_secs: float=300.0):
        self._running = True
        while self._running:
            self.run()
            time.sleep(interval_secs)

    def stop(self):
        self._running = False

    def _compute_metrics(self, run: CycleRun) -> dict[str, float]:
        metrics: dict[str, float] = {}
        completed = [r for r in run.results.values() if r.status == 'completed']
        failed = [r for r in run.results.values() if r.status == 'failed']
        metrics['total_stages'] = float(len(run.results))
        metrics['completed_stages'] = float(len(completed))
        metrics['failed_stages'] = float(len(failed))
        metrics['total_duration_ms'] = run.duration_ms
        if completed:
            metrics['avg_stage_ms'] = sum((r.duration_ms for r in completed)) / len(completed)
        return metrics

    def history(self, limit: int=10) -> list[CycleRun]:
        return list(self._history[-limit:])

    def last_run(self) -> CycleRun | None:
        return self._history[-1] if self._history else None

    def summary(self) -> dict[str, Any]:
        total = len(self._history)
        succeeded = sum((1 for r in self._history if r.status == 'completed'))
        return {'total_cycles': total, 'succeeded': succeeded, 'failed': total - succeeded, 'last_duration_ms': self._history[-1].duration_ms if self._history else 0.0, 'running': self._running}

class EngineeringOrchestrator:
    """Orchestrator that wires platform services into the autonomous cycle."""

    def __init__(self, fabric: FabricKernel | None=None, graph: UnifiedGraph | None=None, ued: Database | None=None, execution: ExecutionEngine | None=None):
        self._fabric = fabric or FabricKernel.instance()
        self._graph = graph or UnifiedGraph()
        self._ued = ued or Database()
        self._execution = execution or ExecutionEngine()
        self._engine = AutonomousEngine()
        self._register_default_handlers()

    def _register_default_handlers(self):
        self._engine.register(CycleStage.OBSERVE, self._observe)
        self._engine.register(CycleStage.ACQUIRE, self._acquire)
        self._engine.register(CycleStage.COMPILE, self._compile)
        self._engine.register(CycleStage.BUILD_IR, self._build_ir)
        self._engine.register(CycleStage.BUILD_TWIN, self._build_twin)
        self._engine.register(CycleStage.UPDATE_GRAPH, self._update_graph)
        self._engine.register(CycleStage.UPDATE_BRAIN, self._update_brain)
        self._engine.register(CycleStage.REASON, self._reason)
        self._engine.register(CycleStage.HYPOTHESIS, self._hypothesis)
        self._engine.register(CycleStage.PLAN, self._plan)
        self._engine.register(CycleStage.SIMULATE, self._simulate)
        self._engine.register(CycleStage.GENERATE_PATCH, self._generate_patch)
        self._engine.register(CycleStage.RUN_TESTS, self._run_tests)
        self._engine.register(CycleStage.BENCHMARK, self._benchmark)
        self._engine.register(CycleStage.VALIDATE, self._validate)
        self._engine.register(CycleStage.PUBLISH, self._publish)
        self._engine.register(CycleStage.LEARN, self._learn)

    def _observe(self, ctx: dict[str, Any]) -> dict[str, Any]:
        self._fabric.send('cycle.observe', {'timestamp': time.time()})
        return {'observed': True, 'targets': ctx.get('targets', [])}

    def _acquire(self, ctx: dict[str, Any]) -> dict[str, Any]:
        self._fabric.send('cycle.acquire', {})
        return {'acquired': True}

    def _compile(self, ctx: dict[str, Any]) -> dict[str, Any]:
        self._fabric.send('cycle.compile', {})
        return {'compiled': True}

    def _build_ir(self, ctx: dict[str, Any]) -> dict[str, Any]:
        structural = self._graph.create_layer('structural', LayerType.STRUCTURAL)
        dep = self._graph.create_layer('dependency', LayerType.DEPENDENCY)
        knowledge = self._graph.create_layer('knowledge', LayerType.KNOWLEDGE)
        return {'structural_nodes': structural.node_count(), 'dependency_nodes': dep.node_count(), 'knowledge_nodes': knowledge.node_count()}

    def _build_twin(self, ctx: dict[str, Any]) -> dict[str, Any]:
        from genesis.meta.twin import WorkspaceTwin
        return {'twin_built': True}

    def _update_graph(self, ctx: dict[str, Any]) -> dict[str, Any]:
        snap = self._graph.snapshot()
        return {'total_nodes': snap.node_count, 'total_edges': snap.edge_count, 'snapshot_id': snap.id}

    def _update_brain(self, ctx: dict[str, Any]) -> dict[str, Any]:
        return {'brain_updated': True}

    def _reason(self, ctx: dict[str, Any]) -> dict[str, Any]:
        self._fabric.send('cycle.reason', {})
        return {'reasoning_complete': True}

    def _hypothesis(self, ctx: dict[str, Any]) -> dict[str, Any]:
        return {'hypotheses': []}

    def _plan(self, ctx: dict[str, Any]) -> dict[str, Any]:
        wf = self._execution.workflows.create('cycle_plan')
        return {'plan_id': wf.id, 'nodes': len(wf.nodes)}

    def _simulate(self, ctx: dict[str, Any]) -> dict[str, Any]:
        return {'simulated': True}

    def _generate_patch(self, ctx: dict[str, Any]) -> dict[str, Any]:
        return {'patches': []}

    def _run_tests(self, ctx: dict[str, Any]) -> dict[str, Any]:
        return {'tests_passed': 0, 'tests_failed': 0}

    def _benchmark(self, ctx: dict[str, Any]) -> dict[str, Any]:
        return {'benchmarks': {}}

    def _validate(self, ctx: dict[str, Any]) -> dict[str, Any]:
        return {'valid': True, 'certificate': ''}

    def _publish(self, ctx: dict[str, Any]) -> dict[str, Any]:
        self._fabric.send('cycle.publish', {'timestamp': time.time()})
        return {'published': True}

    def _learn(self, ctx: dict[str, Any]) -> dict[str, Any]:
        return {'learned': True, 'insights': []}

    def run_cycle(self, context: dict[str, Any] | None=None) -> CycleRun:
        self._fabric.send('cycle.start', {'timestamp': time.time()})
        result = self._engine.run(context)
        self._fabric.send('cycle.complete', {'status': result.status, 'duration_ms': result.duration_ms})
        return result

    @property
    def engine(self) -> AutonomousEngine:
        return self._engine

    def summary(self) -> dict[str, Any]:
        return {'autonomous_engine': self._engine.summary(), 'graph': self._graph.summary()}

class EngineeringBrain:
    """
    Engineering Brain — the universal facade for the platform.

    This is the single entry point for all entity/relationship operations.
    All subsystems communicate through this brain.

    Usage:
        brain = EngineeringBrain(storage_path="brain.db")
        entity = brain.entity(label="MyEntity", entity_type="service")
        brain.register(entity)
        brain.relate(entity_id_1, entity_id_2, "depends_on")
        brain.sync_digital_twin(twin)
    """

    def __init__(self, storage_path: str='', event_bus=None):
        self._graph = BrainGraph(storage_path=storage_path)
        self._embeddings = EmbeddingStore(storage_path=storage_path.replace('.db', '') if storage_path else '')
        self._integration = BrainIntegration(self._graph, event_bus)
        self._cognition = CognitiveArchitecture()
        self._started_at = time.time()
        self._metrics: dict[str, float] = {'entities_registered': 0.0, 'relationships_created': 0.0, 'sync_operations': 0.0}

    @property
    def graph(self) -> BrainGraph:
        return self._graph

    @property
    def embeddings(self) -> EmbeddingStore:
        return self._embeddings

    @property
    def integration(self) -> BrainIntegration:
        return self._integration

    @property
    def cognition(self) -> CognitiveArchitecture:
        """The cognitive architecture (beliefs, goals, reasoning, memory, etc.)."""
        return self._cognition

    def entity(self, label: str='', entity_type: str='unknown', description: str='', source_system: str='', source_id: str='', **kwargs) -> BrainEntity:
        """Create a new BrainEntity (not yet registered)."""
        return BrainEntity(label=label, entity_type=entity_type, description=description, source_system=source_system, source_id=source_id or generate_id(entity_type, 16), **kwargs)

    def register(self, entity: BrainEntity) -> BrainEntity:
        """Register an entity in the brain."""
        result = self._graph.register(entity)
        self._metrics['entities_registered'] += 1
        return result

    def get(self, brain_id: str) -> BrainEntity | None:
        return self._graph.get(brain_id)

    def find_by_type(self, entity_type: str) -> list[BrainEntity]:
        return self._graph.find_by_type(entity_type)

    def find_by_label(self, label_contains: str) -> list[BrainEntity]:
        return self._graph.find_by_label(label_contains)

    def find_by_source(self, source_system: str, source_id: str) -> BrainEntity | None:
        return self._graph.find_by_source(source_system, source_id)

    def remove(self, brain_id: str) -> bool:
        self._embeddings.delete_all(brain_id)
        return self._graph.remove(brain_id)

    def all_entities(self) -> list[BrainEntity]:
        return self._graph.all_entities()

    def relate(self, source_id: str, target_id: str, relation: str='references', weight: float=1.0, **metadata) -> bool:
        result = self._graph.relate(source_id, target_id, relation, weight, **metadata)
        if result:
            self._metrics['relationships_created'] += 1
        return result

    def neighbors(self, brain_id: str, relation: str | None=None) -> list[BrainEntity]:
        return self._graph.get_neighbors(brain_id, relation)

    def relationships(self, brain_id: str) -> list[Relationship]:
        return self._graph.get_relationships(brain_id)

    def sync_digital_twin(self, twin) -> int:
        """Sync all DigitalTwin nodes into the brain."""
        adapter = DigitalTwinAdapter()
        self._metrics['sync_operations'] += 1
        return self._integration.sync_adapter('digital_twin', twin)

    def sync_uir_graph(self, uir_graph) -> int:
        """Sync all UIRGraph nodes into the brain."""
        adapter = UIRAdapter()
        self._metrics['sync_operations'] += 1
        return self._integration.sync_adapter('uir', uir_graph)

    def sync_knowledge_base(self, knowledge_base) -> int:
        """Sync all KnowledgeBase artifacts into the brain."""
        self._metrics['sync_operations'] += 1
        count = 0
        if hasattr(knowledge_base, 'artifacts'):
            adapter = KnowledgeArtifactAdapter()
            for artifact in knowledge_base.artifacts.values():
                try:
                    entity = adapter.to_entity(artifact)
                    self.register(entity)
                    count += 1
                except Exception:
                    pass
        return count

    def sync_vrip_kg(self, vrip_kg) -> int:
        """Sync all VRIP knowledge graph nodes into the brain."""
        adapter = VRIPAdapter()
        self._metrics['sync_operations'] += 1
        return self._integration.sync_adapter('vrip', vrip_kg)

    def sync_graphdb(self, graphdb: PersistentGraphDB) -> int:
        """Sync all PersistentGraphDB nodes into the brain."""
        adapter = GraphDBAdapter()
        self._metrics['sync_operations'] += 1
        return self._integration.sync_adapter('graphdb', graphdb)

    def sync_civilization(self, overseer) -> int:
        """Sync all civilization agents/findings into the brain."""
        self._metrics['sync_operations'] += 1
        count = 0
        if hasattr(overseer, 'agents'):
            adapter = FindingAdapter()
            for agent in overseer.agents.values():
                if hasattr(agent, 'memory') and hasattr(agent.memory, 'findings'):
                    for finding in agent.memory.findings.values():
                        try:
                            entity = adapter.to_entity(finding)
                            entity.attributes['agent_id'] = agent.agent_id
                            entity.attributes['agent_name'] = getattr(agent, 'name', '')
                            self.register(entity)
                            count += 1
                        except Exception:
                            pass
        return count

    def store_embedding(self, entity_id: str, kind: str, vector: list[float], model: str='') -> EntityEmbedding:
        return self._embeddings.store(entity_id, kind, vector, model)

    def get_embedding(self, entity_id: str, kind: str) -> EntityEmbedding | None:
        return self._embeddings.get(entity_id, kind)

    def start_integration(self):
        """Start listening to platform events."""
        self._integration.start()

    def stop_integration(self):
