            chrom_count = genome.chromosome_count
            gene_count = genome.gene_count
            findings.append(ResearchFinding(id=generate_id('arch', 12), title=f'Architectural coupling: {coupling:.4f}', description=f'Repository {genome.repository_name} has coupling {coupling:.4f} ({chrom_count} chromosomes, {gene_count} genes)', evidence=f'Maintainability: {maintainability:.4f}, Species: {genome.species}', confidence=0.8, impact=coupling * 0.5, tags=['architecture', 'coupling', genome.species]))
            findings.append(ResearchFinding(id=generate_id('arch', 12), title=f'Species: {genome.species}', description=f"Classified as '{genome.species}' based on {chrom_count} chromosomes, {genome.total_dependencies} dependencies", evidence=f'Dominant traits: {dict(genome.dominant_traits[:5])}', confidence=0.7, impact=0.3, tags=['species', 'taxonomy', genome.species]))
            if gene_count > 0:
                type_counts: dict[str, int] = {}
                for g in genome.all_genes:
                    type_counts[g.gene_type.name.lower()] = type_counts.get(g.gene_type.name.lower(), 0) + 1
                findings.append(ResearchFinding(id=generate_id('arch', 12), title=f'Gene composition: {len(type_counts)} types', description=f'Gene type distribution: {type_counts}', evidence=f'Total genes: {gene_count}', confidence=0.9, impact=0.2, tags=['composition', 'gene_types']))
        if twin:
            all_edges = []
            if hasattr(twin, 'find_edges'):
                all_edges = twin.find_edges()
            if all_edges:
                hub_modules = self._find_hubs(all_edges)
                if hub_modules:
                    findings.append(ResearchFinding(id=generate_id('arch', 12), title=f'Hubs detected: {len(hub_modules)} modules', description=f'Highly coupled modules: {hub_modules[:5]}', evidence=f'Total edges: {len(all_edges)}', confidence=0.6, impact=-0.3, tags=['hub', 'coupling', 'bottleneck']))
        return findings

    def generate_questions(self, context: dict[str, Any]) -> list[ResearchQuestion]:
        return [ResearchQuestion(question='What is the optimal coupling range for this architecture?', hypothesis='Coupling between 0.3 and 0.7 correlates with highest fitness', priority=0.8, status='open', created_at=time.time()), ResearchQuestion(question='Which modules are architectural bottlenecks?', hypothesis='Modules with >5 incoming dependencies degrade maintainability', priority=0.7, status='open', created_at=time.time()), ResearchQuestion(question='Is there evidence of architectural drift?', hypothesis='Growing module count without layer boundaries indicates drift', priority=0.6, status='open', created_at=time.time())]

    def _find_hubs(self, edges: list, threshold: int=5) -> list[str]:
        targets: dict[str, int] = {}
        for e in edges:
            tgt = e[1] if len(e) > 1 else ''
            targets[tgt] = targets.get(tgt, 0) + 1
        return [m for m, c in sorted(targets.items(), key=lambda x: -x[1]) if c >= threshold][:10]

