            if secrets:
                findings.append(ResearchFinding(id=generate_id('sec', 12), title=f'Potential secrets: {len(secrets)}', description=f'Files with potential secrets: {secrets[:5]}', evidence='Detected using pattern matching', confidence=0.5, impact=-0.7, tags=['security', 'secrets', 'risk']))
        return findings

