class NetworkingScientist(ResearchAgent):
    """Researcher focused on networking protocols, APIs, RPC."""

    def research_domain(self) -> str:
        return 'network_protocols'

    def investigate(self, context: dict[str, Any]) -> list[ResearchFinding]:
        findings = []
        genome = context.get('genome')
        if genome:
            net_genes = [g for g in genome.all_genes if any((kw in (g.name or '').lower() for kw in ('http', 'tcp', 'udp', 'rpc', 'grpc', 'rest', 'api', 'route', 'handler', 'middleware', 'endpoint', 'request', 'response', 'client', 'server', 'socket', 'web', 'ws_')))]
            if net_genes:
                findings.append(ResearchFinding(id=generate_id('net', 12), title=f'Network interfaces: {len(net_genes)}', description=f'Found {len(net_genes)} networking-related abstractions', evidence=f'Interfaces: {[g.name for g in net_genes[:7]]}', confidence=0.85, impact=0.5, tags=['networking', 'protocols', 'api']))
                rest_count = sum((1 for g in net_genes if 'rest' in (g.name or '').lower()))
                rpc_count = sum((1 for g in net_genes if 'rpc' in (g.name or '').lower() or 'grpc' in (g.name or '').lower()))
                websocket_count = sum((1 for g in net_genes if 'ws_' in (g.name or '').lower() or 'websocket' in (g.name or '').lower()))
                if rest_count > rpc_count:
                    findings.append(ResearchFinding(id=generate_id('net', 12), title=f'REST-dominant API style', description=f'REST interfaces ({rest_count}) outnumber RPC ({rpc_count})', evidence='REST-dominant architectures favor resource-oriented design', confidence=0.7, impact=0.2, tags=['networking', 'rest', 'api-style']))
            all_deps = set()
            for g in genome.all_genes:
                all_deps.update(g.dependencies)
            net_deps = [d for d in all_deps if any((lib in d.lower() for lib in ('requests', 'aiohttp', 'flask', 'django', 'fastapi', 'grpc', 'httpx', 'urllib')))]
            if net_deps:
                findings.append(ResearchFinding(id=generate_id('net', 12), title=f'Network libraries: {len(net_deps)}', description=f'Uses networking libraries: {net_deps}', evidence='External dependencies indicate protocol ecosystem', confidence=0.9, impact=0.3, tags=['networking', 'dependencies', 'libraries']))
        return findings

    def generate_questions(self, context: dict[str, Any]) -> list[ResearchQuestion]:
        return [ResearchQuestion(question='What is the API versioning strategy?', hypothesis='Semantic versioning with backward compatibility reduces breakage', priority=0.7, status='open', created_at=time.time()), ResearchQuestion(question='Are there timeout and retry policies?', hypothesis='Missing retry logic with exponential backoff causes cascading failures', priority=0.8, status='open', created_at=time.time())]

